const applyTextScalingDefaults = (Component, componentLabel) => {
  if (!Component) return;
  try {
    if (!Component.defaultProps) Component.defaultProps = {};
    if (Component.defaultProps.allowFontScaling == null) {
      Component.defaultProps.allowFontScaling = true;
    }
    if (Component.defaultProps.maxFontSizeMultiplier == null) {
      Component.defaultProps.maxFontSizeMultiplier = 1.35;
    }
  } catch (error) {
    if (__DEV__) {
      console.warn(`failed to apply text scaling defaults for ${componentLabel}`, error);
    }
  }
};

applyTextScalingDefaults(RNText, "RNText");
applyTextScalingDefaults(RNTextInput, "RNTextInput");

const safeUseFonts =
  typeof useFonts === "function"
    ? useFonts
    : () => {
        if (__DEV__) {
          console.warn("useFonts is unavailable; continuing without custom fonts.");
        }
        return [true, new Error("useFonts is unavailable")];
      };

// Android text intentionally stays on the device/theme font. Do not register bundled families
// there; iOS and web keep the existing Inter typography.
const APP_CUSTOM_FONTS =
  Platform.OS === "android"
    ? {}
    : {
        Inter_300Light,
        Inter_400Regular,
        Inter_500Medium,
        Inter_600SemiBold,
        Inter_700Bold,
        Inter_800ExtraBold,
        Inter_900Black,
      };
const safeUseSafeAreaInsets =
  typeof useSafeAreaInsets === "function"
    ? useSafeAreaInsets
    : () => {
        if (__DEV__) {
          console.warn("useSafeAreaInsets is unavailable; using zero insets.");
        }
        return { top: 0, bottom: 0, left: 0, right: 0 };
      };

