  ARS: [/\b(?:ARS|AR)[\s\u00A0\u202F]*\$/gi, /\$[\s\u00A0\u202F]*(?:ARS|AR)(?=$|[^A-Za-z])/gi],
  CAD: [/\b(?:CAD|CA|C)[\s\u00A0\u202F]*\$/gi, /\$[\s\u00A0\u202F]*(?:CAD|CA|C)(?=$|[^A-Za-z])/gi],
