const TAMAGOTCHI_SKIN_ASSET_BASE_URL_RC_KEY = "tamagotchi_skin_asset_base_url";
const DEFAULT_TAMAGOTCHI_SKIN_ASSET_BASE_URL =
  "https://almost-monetization-backend.onrender.com/assets";
