const buildDailyNudgeTrigger = (hour, minute, options = {}) => {
  const { repeats = true, allowPast = false } = options || {};
  if (!repeats) {
    const now = new Date();
    const target = new Date(now);
    target.setHours(hour, minute, 0, 0);
    if (target.getTime() <= now.getTime()) {
      if (!allowPast) return null;
      target.setDate(target.getDate() + 1);
    }
    return target;
  }
  if (Platform.OS === "android") {
    const now = new Date();
    const next = new Date(now);
    next.setHours(hour, minute, 0, 0);
    if (next.getTime() <= now.getTime()) {
      next.setDate(next.getDate() + 1);
    }
    return next;
  }
  return { hour, minute, second: 0, repeats: true };
};


const normalizeSmartReminderEntries = (list) => {
  const now = Date.now();
  const seen = new Set();
  const normalized = [];
  (Array.isArray(list) ? list : []).forEach((entry) => {
    if (!entry) return;
    const timestamp = Number(entry.timestamp);
    if (!Number.isFinite(timestamp)) return;
    if (now - timestamp > SMART_REMINDER_RETENTION_MS) return;
    const eventId = entry.eventId || entry.id;
    if (!eventId || seen.has(eventId)) return;
    seen.add(eventId);
    normalized.push({
      id: entry.id || `smart-${eventId}`,
      eventId,
      kind: typeof entry.kind === "string" ? entry.kind : "refuse_spend",
      title: typeof entry.title === "string" ? entry.title : "",
      timestamp,
      scheduledAt: Number(entry.scheduledAt) || timestamp + SMART_REMINDER_DELAY_MS,
      notificationId: entry.notificationId || null,
      templateId: typeof entry.templateId === "string" ? entry.templateId : null,
    });
  });
  normalized.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
  return normalized.slice(0, SMART_REMINDER_LIMIT);
};

const IDENTICAL_PUSH_TIME_WINDOW_MS = 90 * 1000;
const NOTIFICATION_CONTENT_DEDUPE_RETENTION_MS = 24 * 60 * 60 * 1000;
const NOTIFICATION_RESPONSE_DEDUPE_WINDOW_MS = 20 * 1000;

const normalizeNotificationText = (value) => {
  if (typeof value !== "string") return "";
  return value.trim().replace(/\s+/g, " ").toLowerCase();
};

const buildNotificationContentSignature = (content) => {
  if (!content || typeof content !== "object") return "";
  const title = normalizeNotificationText(content.title);
  const subtitle = normalizeNotificationText(content.subtitle);
  const body = normalizeNotificationText(content.body);
  const data = content.data && typeof content.data === "object" ? content.data : {};
  const kind = normalizeNotificationText(typeof data.kind === "string" ? data.kind : "");
  if (!title && !subtitle && !body) return "";
  return [kind, title, subtitle, body].join("|");
};

const pruneNotificationSignatureMap = (
  map,
  nowTs,
  ttlMs = NOTIFICATION_CONTENT_DEDUPE_RETENTION_MS
) => {
  if (!(map instanceof Map)) return;
  const threshold = nowTs - Math.max(0, Number(ttlMs) || 0);
  for (const [key, value] of map.entries()) {
    const timestamp = Number(value) || 0;
    if (timestamp <= 0 || timestamp < threshold) {
      map.delete(key);
    }
  }
};

const DEFERRED_STORAGE_PARSE_THRESHOLD = 120000;
const shouldDeferLargeParse = (raw) =>
  typeof raw === "string" && raw.length >= DEFERRED_STORAGE_PARSE_THRESHOLD;
const deferNonFeedHydration = (task) => {
  InteractionManager.runAfterInteractions(task);
};

const minuteTicker = (() => {
  let subscribers = new Set();
  let timeoutId = null;
  let intervalId = null;
  const notify = () => {
    const now = Date.now();
    subscribers.forEach((cb) => cb(now));
  };
  const clear = () => {
    if (timeoutId) clearTimeout(timeoutId);
    if (intervalId) clearInterval(intervalId);
    timeoutId = null;
    intervalId = null;
  };
  const schedule = () => {
    clear();
    const now = Date.now();
    const delay = 60000 - (now % 60000);
    timeoutId = setTimeout(() => {
      notify();
      intervalId = setInterval(notify, 60000);
    }, delay);
  };
  return {
    subscribe(callback) {
      subscribers.add(callback);
      if (subscribers.size === 1) {
        schedule();
      }
      return () => {
        subscribers.delete(callback);
        if (!subscribers.size) {
          clear();
        }
      };
    },
  };
})();

const useMinuteTicker = (active = true) => {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!active) return undefined;
    setNow(Date.now());
    return minuteTicker.subscribe(setNow);
  }, [active]);
  return active ? now : null;
};

const resolveInterFontFamily = (fontWeight) => {
  if (typeof fontWeight === "string") {
    if (fontWeight.toLowerCase() === "bold") return INTER_FONTS.bold;
    if (fontWeight.toLowerCase() === "normal") return INTER_FONTS.regular;
  }
  const numericWeight = Number(fontWeight) || 0;
  if (numericWeight >= 900) return INTER_FONTS.black;
  if (numericWeight >= 800) return INTER_FONTS.extraBold;
  if (numericWeight >= 700) return INTER_FONTS.bold;
  if (numericWeight >= 600) return INTER_FONTS.semiBold;
  if (numericWeight >= 500) return INTER_FONTS.medium;
  if (numericWeight >= 300) return INTER_FONTS.light;
  return INTER_FONTS.regular;
};

const INTER_FONT_WEIGHT_BY_FAMILY = Object.freeze({
  [INTER_FONTS.light]: "300",
  [INTER_FONTS.regular]: "400",
  [INTER_FONTS.medium]: "500",
  [INTER_FONTS.semiBold]: "600",
  [INTER_FONTS.bold]: "700",
  [INTER_FONTS.extraBold]: "800",
  [INTER_FONTS.black]: "900",
});

const resolveAndroidSystemFontWeight = (fontFamily, fontWeight) => {
  if (fontWeight !== undefined && fontWeight !== null && fontWeight !== "") {
    return fontWeight;
  }
  return INTER_FONT_WEIGHT_BY_FAMILY[fontFamily];
};

const FormattingLanguageContext = React.createContext(DEFAULT_LANGUAGE);
