const getMoodGradient = (moodId = MOOD_IDS.NEUTRAL) =>
  MOOD_GRADIENTS[moodId] || MOOD_GRADIENTS[MOOD_IDS.NEUTRAL];

const applyThemeToMoodGradient = (palette, themeKey = "light", themeColors = null) => {
  if (!palette) return getMoodGradient();
  const resolvedThemeColors = themeColors || THEMES[themeKey] || THEMES[DEFAULT_THEME];
  if (themeKey === PRO_THEME_ID) {
    const mix = MOOD_GRADIENT_THEME_MIX.pro;
    return {
      start: blendColors(resolvedThemeColors.background, palette.start, mix.startMoodMix),
      end: blendColors(resolvedThemeColors.surfaceMuted, palette.end, mix.endMoodMix),
      accent: blendColors(palette.accent, resolvedThemeColors.primary, mix.accentPrimaryMix),
    };
  }
  if (themeKey !== "dark") return palette;
  const mix = MOOD_GRADIENT_THEME_MIX.dark;
  return {
    start: blendColors(resolvedThemeColors.surface, palette.accent, mix.startAccentMix),
    end: blendColors(resolvedThemeColors.background, palette.accent, mix.endAccentMix),
    accent: blendColors(palette.accent, resolvedThemeColors.text, mix.accentTextMix),
  };
};

const MoodGradientBlock = ({ colors: palette, style, children, onLayout }) => {
  const gradientColors = palette || MOOD_GRADIENTS[MOOD_IDS.NEUTRAL];
  return (
    <View
      style={[
        styles.moodGradientBlock,
        { backgroundColor: gradientColors.start },
        style,
      ]}
      onLayout={onLayout}
    >
      <View
        pointerEvents="none"
        style={[
          styles.moodGradientOverlay,
          { backgroundColor: gradientColors.end },
        ]}
      />
      {children}
    </View>
  );
};

const CoinRainOverlay = React.memo(function CoinRainOverlay({ dropCount = 14, asset = null, assets = null }) {
  const assetPool = Array.isArray(assets) ? assets.filter(Boolean) : [];
  const fallbackAsset = asset || HEALTH_COIN_TIERS[0]?.asset || null;
  const resolvedPool = assetPool.length ? assetPool : fallbackAsset ? [fallbackAsset] : [];
  const normalizedDropCount = Math.max(0, Math.min(10, Math.floor(Number(dropCount) || 0)));
  const shouldRenderCoinRain = Platform.OS !== "android" && resolvedPool.length > 0 && normalizedDropCount > 0;
  const dropsRef = useRef([]);
  const dropSignatureRef = useRef(null);
  const dropSignature = `${normalizedDropCount}:${resolvedPool.length}`;
  if (dropSignatureRef.current !== dropSignature) {
    dropsRef.current = Array.from({ length: normalizedDropCount }).map((_, idx) => {
      const anim = new Animated.Value(0);
      return {
        key: `coin_rain_${idx}`,
        anim,
        left: Math.random() * (SCREEN_WIDTH - 40),
        size: 20 + Math.random() * 14,
        duration: 4200 + Math.random() * 1800,
        delay: Math.random() * 520,
        assetIndex: resolvedPool.length ? idx % resolvedPool.length : 0,
      };
    });
    dropSignatureRef.current = dropSignature;
  }
  const drops = dropsRef.current;

  useEffect(() => {
    if (!shouldRenderCoinRain) return undefined;
    const animations = drops.map(({ anim, duration, delay }) => {
      const animation = Animated.sequence([
        Animated.delay(delay),
        Animated.timing(anim, {
          toValue: 1,
          duration,
          easing: Easing.out(Easing.cubic),
          useNativeDriver: true,
        }),
      ]);
      animation.start();
      return animation;
    });
    return () => {
      animations.forEach((animation) => animation?.stop?.());
    };
  }, [drops, shouldRenderCoinRain]);

  if (!shouldRenderCoinRain) return null;

  return (
    <View pointerEvents="none" style={StyleSheet.absoluteFillObject}>
      {drops.map(({ key, anim, left, size, assetIndex }) => {
        const translateY = anim.interpolate({
          inputRange: [0, 1],
          outputRange: [-160, Dimensions.get("window").height + 120],
        });
        const translateX = anim.interpolate({
          inputRange: [0, 0.2, 0.5, 0.8, 1],
          outputRange: [left - 16, left + 12, left - 8, left + 6, left - 2],
        });
        const opacity = anim.interpolate({
          inputRange: [0, 0.15, 0.85, 1],
          outputRange: [0, 0.9, 0.8, 0],
        });
        const rotate = anim.interpolate({
          inputRange: [0, 1],
          outputRange: ["180deg", "540deg"],
        });
        return (
          <Animated.Image
            key={key}
            source={resolvedPool[assetIndex] || resolvedPool[0]}
            style={{
              position: "absolute",
              left: 0,
              width: size,
              height: size,
              opacity,
              transform: [
                { translateX },
                { translateY },
                { rotate },
              ],
            }}
            resizeMode="contain"
          />
        );
      })}
    </View>
  );
});

