const getFeedCardOrderKey = (item) => {
  if (!item || typeof item !== "object") return "";
  const id = item.id;
  if (typeof id === "string" && id.trim()) return `id:${id.trim()}`;
  if (typeof id === "number" && Number.isFinite(id)) return `id:${id}`;
  const templateId = item.templateId;
  if (typeof templateId === "string" && templateId.trim()) {
    return `template:${templateId.trim()}`;
  }
  if (typeof templateId === "number" && Number.isFinite(templateId)) {
    return `template:${templateId}`;
  }
  return "";
};

const normalizeFeedCardOrder = (value) => {
  if (!Array.isArray(value)) return [];
  const seen = new Set();
  const normalized = [];
  for (const entry of value) {
    if (normalized.length >= FEED_CARD_ORDER_MAX_ITEMS) break;
    const key =
      typeof entry === "string"
        ? entry.trim()
        : typeof entry === "number" && Number.isFinite(entry)
        ? String(entry)
        : "";
    if (!key || seen.has(key)) continue;
    seen.add(key);
    normalized.push(key);
  }
  return normalized;
};

const areFeedCardOrdersEqual = (left, right) => {
  if (left === right) return true;
  if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) {
    return false;
  }
  return left.every((entry, index) => entry === right[index]);
};

const mergeFeedCardOrder = (storedOrder, products) => {
  const sourceKeys = [];
  const sourceKeySet = new Set();
  (Array.isArray(products) ? products : []).forEach((item) => {
    const key = getFeedCardOrderKey(item);
    if (!key || sourceKeySet.has(key)) return;
    sourceKeySet.add(key);
    sourceKeys.push(key);
  });
  const merged = normalizeFeedCardOrder(storedOrder).filter((key) => sourceKeySet.has(key));
  const mergedSet = new Set(merged);
  sourceKeys.forEach((key) => {
    if (mergedSet.has(key)) return;
    mergedSet.add(key);
    merged.push(key);
  });
  return merged;
};

const applyVisibleFeedCardOrder = (fullOrder, visibleOrder) => {
  const normalizedFullOrder = normalizeFeedCardOrder(fullOrder);
  const normalizedVisibleOrder = normalizeFeedCardOrder(visibleOrder);
  if (!normalizedVisibleOrder.length) return normalizedFullOrder;
  const visibleSet = new Set(normalizedVisibleOrder);
  let visibleIndex = 0;
  const reordered = normalizedFullOrder.map((key) => {
    if (!visibleSet.has(key)) return key;
    const nextKey = normalizedVisibleOrder[visibleIndex];
    visibleIndex += 1;
    return nextKey || key;
  });
  while (visibleIndex < normalizedVisibleOrder.length) {
    reordered.push(normalizedVisibleOrder[visibleIndex]);
    visibleIndex += 1;
  }
  return normalizeFeedCardOrder(reordered);
};

const normalizeImpulseAlertRecord = (value) => {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    const shownAt = Number(value.shownAt ?? value.lastShownAt ?? value.timestamp ?? 0) || 0;
    const rawDayKey = typeof value.dayKey === "string" ? value.dayKey.trim() : "";
    const dayKey = parseDayKey(rawDayKey) ? rawDayKey : shownAt > 0 ? getDayKey(shownAt) : "";
    return dayKey ? { dayKey, shownAt } : null;
  }
  if (typeof value === "number" && Number.isFinite(value) && value > 0) {
    return { dayKey: getDayKey(value), shownAt: value };
  }
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (parseDayKey(trimmed)) {
      return { dayKey: trimmed, shownAt: 0 };
    }
    const parsed = Date.parse(trimmed);
    if (Number.isFinite(parsed)) {
      return { dayKey: getDayKey(parsed), shownAt: parsed };
    }
  }
  return null;
};

const normalizeImpulseAlertMap = (value) => {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return Object.entries(value).reduce((acc, [templateId, record]) => {
    if (typeof templateId !== "string" || !templateId.trim()) return acc;
    const normalized = normalizeImpulseAlertRecord(record);
    if (!normalized) return acc;
    acc[templateId.trim()] = normalized;
    return acc;
  }, {});
};

const DEFAULT_INCOME_PAYDAY = 1;
const CATEGORY_BUDGET_MONTH_PAYDAY = DEFAULT_INCOME_PAYDAY;
const normalizeIncomePayday = (value, fallback = DEFAULT_INCOME_PAYDAY) => {
  const parsed = Number(value);
  if (Number.isFinite(parsed) && parsed >= 1 && parsed <= 31) {
    return Math.round(parsed);
  }
  const fallbackParsed = Number(fallback);
  if (Number.isFinite(fallbackParsed) && fallbackParsed >= 1 && fallbackParsed <= 31) {
    return Math.round(fallbackParsed);
  }
  return DEFAULT_INCOME_PAYDAY;
};
const createIncomeEntryInputState = (payday = DEFAULT_INCOME_PAYDAY) => ({
  amount: "",
  payday: normalizeIncomePayday(payday),
});
const INCOME_ENTRY_DAY_OPTIONS = Array.from({ length: 31 }, (_, index) => index + 1);
const resolveIncomeEntryReceivedAt = (payday = DEFAULT_INCOME_PAYDAY, baseTimestamp = Date.now()) => {
  const baseDate = new Date(baseTimestamp);
  if (Number.isNaN(baseDate.getTime())) return Date.now();
  const daysInMonth = new Date(baseDate.getFullYear(), baseDate.getMonth() + 1, 0).getDate();
  const resolvedDay = Math.min(normalizeIncomePayday(payday, baseDate.getDate()), daysInMonth);
  return new Date(
    baseDate.getFullYear(),
    baseDate.getMonth(),
    resolvedDay,
    baseDate.getHours(),
    baseDate.getMinutes(),
    baseDate.getSeconds(),
    baseDate.getMilliseconds()
  ).getTime();
};
