const SUBSCRIPTION_REMINDER_KIND = "subscription_reminder";
const SUBSCRIPTION_DUE_KIND = "subscription_due";
const SUBSCRIPTION_EMPTY_EMOJIS = ["📺", "🎧", "🧾"];
const SUBSCRIPTION_DEFAULT_REMINDER_HOUR = 10;
const SUBSCRIPTION_DEFAULT_REMINDER_MINUTE = 0;

const DEFAULT_SAVINGS_CATEGORY_DEF = {
  id: "savings",
  ru: "Сбережения",
  en: "Savings",
  es: "Ahorros",
  fr: "Épargne",
  emoji: "💎",
};
const BUDGET_SPECIAL_CATEGORY_DEFS = {
  savings: { ...DEFAULT_SAVINGS_CATEGORY_DEF },
};
const BUDGET_DEFAULT_FLEX_WEIGHT = 0.08;
const BUDGET_CATEGORY_META = {
  savings: { group: "savings" },
  rent: { group: "essential", baseWeight: 0.25 },
  utilities: { group: "essential", baseWeight: 0.08 },
  car: { group: "essential", baseWeight: 0.06 },
  mandatory: { group: "essential", baseWeight: 0.08 },
  food: { group: "essential", baseWeight: 0.12 },
  transport: { group: "essential", baseWeight: 0.06 },
  health: { group: "flex", fallbackWeight: 0.1 },
  subscriptions: { group: "flex", fallbackWeight: 0.08 },
  home: { group: "flex", fallbackWeight: 0.08 },
  fun: { group: "flex", fallbackWeight: 0.12 },
  things: { group: "flex", fallbackWeight: 0.14 },
  beauty: { group: "flex", fallbackWeight: 0.08 },
  clothing: { group: "flex", fallbackWeight: 0.08 },
  education: { group: "flex", fallbackWeight: 0.08 },
  pets: { group: "flex", fallbackWeight: 0.08 },
  vices: { group: "flex", fallbackWeight: 0.08 },
};

const getBudgetCategoryOrder = () => {
  const order = ["savings", ...IMPULSE_CATEGORY_ORDER];
  return Array.from(new Set(order));
};

const getBudgetCategoryMeta = (id) => {
  if (BUDGET_CATEGORY_META[id]) return BUDGET_CATEGORY_META[id];
  if (id === "savings") return { group: "savings" };
  return { group: "flex", fallbackWeight: BUDGET_DEFAULT_FLEX_WEIGHT };
};

const getBudgetCategoryLabel = (id, language = DEFAULT_LANGUAGE) => {
  if (id === "savings") {
    const entry = BUDGET_SPECIAL_CATEGORY_DEFS.savings;
    const key = getShortLanguageKey(language);
    const normalizedLanguage = normalizeLanguage(language);
    const translationLanguage = resolveTranslationLanguage(normalizedLanguage);
    const rawLabel =
      entry[normalizedLanguage] ||
      entry[translationLanguage] ||
      entry[key] ||
      entry.en ||
      entry.ru ||
      id;
    return localizeFallbackTextByLanguage(rawLabel, normalizedLanguage);
  }
  return getImpulseCategoryName(id, language);
};

const getBudgetCategoryEmoji = (id) => {
  if (id === "savings") return BUDGET_SPECIAL_CATEGORY_DEFS.savings?.emoji || "💎";
  return IMPULSE_CATEGORY_DEFS[id]?.emoji || "✨";
};

const isUserSubscriptionTemptation = (item = null, categoryId = null) => {
  if (!item || typeof item !== "object") return false;
  const hasExplicitSubscriptionOverride =
    item.impulseCategoryOverride === SUBSCRIPTION_CATEGORY_ID ||
    item.impulseCategory === SUBSCRIPTION_CATEGORY_ID;
  if (hasExplicitSubscriptionOverride) return true;
  const isUserCreated =
    item.quickTemptation === true ||
    isCustomTemptation(item) ||
    (typeof item.id === "string" && item.id.startsWith("custom_habit_"));
  if (!isUserCreated) return false;
  const categories = Array.isArray(item.categories) ? item.categories : [];
  return (
    categoryId === SUBSCRIPTION_CATEGORY_ID ||
    item.impulseCategoryOverride === SUBSCRIPTION_CATEGORY_ID ||
    item.impulseCategory === SUBSCRIPTION_CATEGORY_ID ||
    categories.includes(SUBSCRIPTION_CATEGORY_ID)
  );
};

const resolveSubscriptionScheduleConfig = (item = null, interactionEntry = null) => {
  const entry = interactionEntry && typeof interactionEntry === "object" ? interactionEntry : {};
  const frequency = normalizeFrequencyId(entry.frequency || item?.frequency) || "monthly";
  const frequencyCustom =
    frequency === "custom"
      ? normalizeCustomFrequency(entry.frequencyCustom || item?.frequencyCustom) || {
          ...DEFAULT_CUSTOM_FREQUENCY,
        }
      : null;
  const reminderTime =
    normalizeFrequencyReminderTime({
      hour: entry.frequencyReminderHour ?? item?.frequencyReminderHour,
      minute: entry.frequencyReminderMinute ?? item?.frequencyReminderMinute,
    }) || {
      hour: SUBSCRIPTION_DEFAULT_REMINDER_HOUR,
      minute: SUBSCRIPTION_DEFAULT_REMINDER_MINUTE,
    };
  const weeklyDays =
    normalizeFrequencyWeeklyDays(
      entry.frequencyWeeklyDays ?? entry.frequencyWeeklyDay ?? item?.frequencyWeeklyDays ?? item?.frequencyWeeklyDay
    ) || [...DEFAULT_FREQUENCY_WEEKLY_DAYS];
  const monthlyDays =
    normalizeFrequencyMonthlyDays(
      entry.frequencyMonthlyDays ??
        entry.frequencyMonthlyDay ??
        item?.frequencyMonthlyDays ??
        item?.frequencyMonthlyDay
    ) || [...DEFAULT_FREQUENCY_MONTHLY_DAYS];
  return {
    entry,
    frequency,
    frequencyCustom,
    reminderTime,
    weeklyDays,
    monthlyDays,
  };
};

const resolveSubscriptionNextCheckAt = (item = null, interactionEntry = null, nowTs = Date.now()) => {
  const { entry, frequency, frequencyCustom, reminderTime, weeklyDays, monthlyDays } =
    resolveSubscriptionScheduleConfig(item, interactionEntry);
  const storedNextCheckAt = Number(entry.nextCheckAt);
  if (Number.isFinite(storedNextCheckAt) && storedNextCheckAt > nowTs - DAY_MS) {
    return storedNextCheckAt;
  }
  const baseTimestamp =
    Number(entry.lastTimerResetAt) ||
    Number(entry.firstTimerConfiguredAt) ||
    Number(entry.lastInteractionAt) ||
    Number(item?.createdAt) ||
    nowTs;
  return buildResetNextCheckAtForFrequency({
    fromTimestamp: baseTimestamp,
    frequencyId: frequency,
    customFrequency: frequencyCustom,
    reminderHour: reminderTime.hour,
    reminderMinute: reminderTime.minute,
    weeklyDay: weeklyDays[0] ?? DEFAULT_FREQUENCY_WEEKLY_DAY,
    monthlyDay: monthlyDays[0] ?? DEFAULT_FREQUENCY_MONTHLY_DAY,
    weeklyDays,
    monthlyDays,
  });
};

const resolveSubscriptionDueState = (item = null, interactionEntry = null, nowTs = Date.now()) => {
  const { entry, frequency, frequencyCustom } = resolveSubscriptionScheduleConfig(item, interactionEntry);
  const nextCheckAt = resolveSubscriptionNextCheckAt(item, entry, nowTs);
  const storedNextCheckAt = Number(entry.nextCheckAt);
  const missedCycles = Math.max(0, Math.floor(Number(entry.missedCycles) || 0));
  const lastInteractionAt = Math.max(0, Number(entry.lastInteractionAt) || 0);
  const lastMissedCheckAt = Math.max(0, Number(entry.lastMissedCheckAt) || 0);
  const intervalMs =
    Math.max(0, Number(entry.intervalMs) || 0) ||
    resolveFrequencyIntervalMs(frequency, frequencyCustom) ||
    0;
  let dueAt = null;
  let dueCycles = 0;
  if (Number.isFinite(storedNextCheckAt) && storedNextCheckAt > 0 && storedNextCheckAt <= nowTs) {
    dueAt = storedNextCheckAt;
    dueCycles = Math.max(1, missedCycles + 1);
  } else if (missedCycles > 0) {
    if (lastMissedCheckAt > 0) {
      dueAt = lastMissedCheckAt;
    } else if (Number.isFinite(storedNextCheckAt) && storedNextCheckAt > nowTs && intervalMs > 0) {
      dueAt = storedNextCheckAt - missedCycles * intervalMs;
    }
    dueCycles = missedCycles;
  } else if (
    !(Number.isFinite(storedNextCheckAt) && storedNextCheckAt > 0) &&
    lastInteractionAt > 0 &&
    intervalMs > 0 &&
    lastInteractionAt + intervalMs <= nowTs
  ) {
    dueAt = lastInteractionAt + intervalMs;
    dueCycles = 1;
  }
  if (!Number.isFinite(dueAt) || dueAt <= 0 || dueAt > nowTs) {
    return { isDue: false, dueAt: null, dueCycles: 0, nextCheckAt };
  }
  if (lastInteractionAt >= dueAt) {
    return { isDue: false, dueAt: null, dueCycles: 0, nextCheckAt };
  }
  return {
    isDue: true,
    dueAt,
    dueCycles: Math.max(1, dueCycles),
    nextCheckAt,
  };
};

const resolveSubscriptionChecksPerMonth = (item = null, interactionEntry = null) => {
  const entry = interactionEntry && typeof interactionEntry === "object" ? interactionEntry : {};
  const frequency = normalizeFrequencyId(entry.frequency || item?.frequency) || "monthly";
  return resolveFrequencyChecksPerMonth({
    frequencyId: frequency,
    customFrequency: entry.frequencyCustom || item?.frequencyCustom || null,
    weeklyDays: entry.frequencyWeeklyDays ?? entry.frequencyWeeklyDay ?? item?.frequencyWeeklyDays ?? item?.frequencyWeeklyDay,
    monthlyDays:
      entry.frequencyMonthlyDays ??
      entry.frequencyMonthlyDay ??
      item?.frequencyMonthlyDays ??
      item?.frequencyMonthlyDay,
  });
};

const getMonthKey = (value = Date.now()) => {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const year = date.getFullYear();
  const month = `${date.getMonth() + 1}`.padStart(2, "0");
  return `${year}-${month}`;
};

const resolveBudgetPeriodStartDate = (
  value = Date.now(),
  payday = DEFAULT_INCOME_PAYDAY
) => {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  const normalizedPayday = normalizeIncomePayday(payday);
  const start = new Date(date.getFullYear(), date.getMonth(), 1);
  const daysInMonth = new Date(start.getFullYear(), start.getMonth() + 1, 0).getDate();
  start.setDate(Math.min(normalizedPayday, daysInMonth));
  start.setHours(0, 0, 0, 0);
  if (date.getTime() >= start.getTime()) return start;
  const previous = new Date(date.getFullYear(), date.getMonth() - 1, 1);
  const previousDaysInMonth = new Date(
    previous.getFullYear(),
    previous.getMonth() + 1,
    0
  ).getDate();
  previous.setDate(Math.min(normalizedPayday, previousDaysInMonth));
  previous.setHours(0, 0, 0, 0);
  return previous;
};

const resolveBudgetPeriodStartDateForKey = (
  periodKey,
  payday = DEFAULT_INCOME_PAYDAY
) => {
  const parsed = parseMonthKey(periodKey);
  if (!parsed) return null;
  const daysInMonth = new Date(parsed.getFullYear(), parsed.getMonth() + 1, 0).getDate();
  parsed.setDate(Math.min(normalizeIncomePayday(payday), daysInMonth));
  parsed.setHours(0, 0, 0, 0);
  return parsed;
};

const resolveBudgetPeriodEndDateForStart = (
  startDate,
  payday = DEFAULT_INCOME_PAYDAY
) => {
  if (!(startDate instanceof Date) || Number.isNaN(startDate.getTime())) return null;
  const end = new Date(startDate.getFullYear(), startDate.getMonth() + 1, 1);
  const daysInMonth = new Date(end.getFullYear(), end.getMonth() + 1, 0).getDate();
  end.setDate(Math.min(normalizeIncomePayday(payday), daysInMonth));
  end.setHours(0, 0, 0, 0);
  return end;
};

const getBudgetPeriodKey = (value = Date.now(), payday = DEFAULT_INCOME_PAYDAY) => {
  const start = resolveBudgetPeriodStartDate(value, payday);
  return start ? getMonthKey(start.getTime()) : "";
};

const resolveBudgetPeriodInfo = ({
  periodKey = "",
  payday = DEFAULT_INCOME_PAYDAY,
  now = Date.now(),
} = {}) => {
  const start = resolveBudgetPeriodStartDateForKey(periodKey, payday);
  const end = resolveBudgetPeriodEndDateForStart(start, payday);
  if (!start || !end) {
    return {
      startAt: 0,
      endAt: 0,
      durationMs: 0,
      elapsedRatio: 0,
      remainingRatio: 1,
      isCurrentPeriod: false,
      isPastPeriod: false,
    };
  }
  const startAt = start.getTime();
  const endAt = end.getTime();
  const durationMs = Math.max(DAY_MS, endAt - startAt);
  const normalizedNow = normalizeTemporalMs(now, Date.now());
  const currentPeriodKey = getBudgetPeriodKey(normalizedNow, payday);
  const elapsedMs = clampNumber((normalizedNow - startAt) / durationMs, 0, 1) * durationMs;
  return {
    startAt,
    endAt,
    durationMs,
    elapsedRatio: clampNumber(elapsedMs / durationMs, 0, 1),
    remainingRatio: clampNumber((endAt - normalizedNow) / durationMs, 0, 1),
    isCurrentPeriod: currentPeriodKey === periodKey,
    isPastPeriod: periodKey < currentPeriodKey,
  };
};

const parseMonthKey = (key) => {
  if (typeof key !== "string" || key.trim().length === 0) return null;
  const [yearStr, monthStr] = key.split("-");
  const year = Number(yearStr);
  const month = Number(monthStr);
  if (!year || !month) return null;
  const date = new Date(year, month - 1, 1);
  if (Number.isNaN(date.getTime())) return null;
  date.setHours(0, 0, 0, 0);
  return date;
};

const getMonthLabel = (value = Date.now(), locale = "en-US") => {
  try {
    const date = new Date(value);
    return date.toLocaleDateString(locale, { month: "long", year: "numeric" });
  } catch {
    return "";
  }
};

const getMonthLabelForKey = (monthKey, locale = "en-US") => {
  const parsed = parseMonthKey(monthKey);
  if (!parsed) return "";
  return getMonthLabel(parsed, locale);
};

const INCOME_ENTRY_TYPES = {
  MONTHLY: "monthly",
  EXTRA: "extra",
};

const normalizeTemporalMs = (value, fallback = 0) => {
  if (value === null || value === undefined) return fallback;
  let parsed = 0;
  if (typeof value === "number") {
    parsed = value;
  } else if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return fallback;
    const numericValue = Number(trimmed);
    if (Number.isFinite(numericValue)) {
      parsed = numericValue;
    } else {
      const dateValue = Date.parse(trimmed);
      parsed = Number.isFinite(dateValue) ? dateValue : 0;
    }
  } else if (value instanceof Date) {
    parsed = value.getTime();
  } else if (typeof value === "object") {
    const objectValue = value;
    const secondsCandidate = Number(
      objectValue.seconds ?? objectValue._seconds ?? objectValue.sec ?? 0
    );
    const nanosCandidate = Number(
      objectValue.nanoseconds ?? objectValue._nanoseconds ?? objectValue.nanos ?? 0
    );
    if (Number.isFinite(secondsCandidate) && secondsCandidate > 0) {
      parsed = secondsCandidate * 1000 + (Number.isFinite(nanosCandidate) ? nanosCandidate / 1e6 : 0);
    } else if (typeof objectValue.toMillis === "function") {
      const millisValue = Number(objectValue.toMillis());
      parsed = Number.isFinite(millisValue) ? millisValue : 0;
    } else if (typeof objectValue.toDate === "function") {
      const dateValue = objectValue.toDate();
      parsed = dateValue instanceof Date ? dateValue.getTime() : 0;
    } else if (Object.prototype.hasOwnProperty.call(objectValue, "timestamp")) {
      const nestedTimestamp = objectValue.timestamp;
      if (nestedTimestamp !== value) {
        parsed = normalizeTemporalMs(nestedTimestamp, 0);
      }
    }
  }
  if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
  // Handle legacy timestamps that may be in seconds/microseconds/nanoseconds.
  if (parsed > 1e18) {
    parsed = Math.round(parsed / 1e6);
  } else if (parsed > 1e15) {
    parsed = Math.round(parsed / 1e3);
  } else if (parsed < 1e11) {
    parsed = Math.round(parsed * 1e3);
  }
  if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
  return parsed;
};

const SUBSCRIPTION_AUTO_IMPORT_MIN_MONTHLY_REPEATS = 2;
const SUBSCRIPTION_AUTO_IMPORT_MIN_WEEKLY_REPEATS = 3;
const SUBSCRIPTION_AUTO_IMPORT_LOOKBACK_MS = DAY_MS * 400;
const SUBSCRIPTION_AUTO_IMPORT_AMOUNT_TOLERANCE = 0.22;
const SUBSCRIPTION_AUTO_IMPORT_MAX_CANDIDATES = 8;

const normalizeSubscriptionAutoImportTitle = (value = "") =>
  stripEmojis(String(value || ""))
    .replace(/[^\p{L}\p{N}\s._-]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();

const getSubscriptionAutoImportKey = (value = "") =>
  normalizeSubscriptionAutoImportTitle(value).toLowerCase().replace(/[\s._-]+/g, " ").trim();

const hashSubscriptionAutoImportKey = (value = "") => {
  const source = String(value || "");
  let hash = 0;
  for (let index = 0; index < source.length; index += 1) {
    hash = (hash * 31 + source.charCodeAt(index)) | 0;
  }
  return Math.abs(hash).toString(36);
};

const getSubscriptionAutoImportExistingKeys = (cards = []) => {
  const keys = new Set();
  (Array.isArray(cards) ? cards : []).forEach((card) => {
    const title = normalizeSubscriptionAutoImportTitle(card?.title || card?.templateTitle || "");
    const titleKey = getSubscriptionAutoImportKey(title);
    if (titleKey) keys.add(titleKey);
    const id = typeof card?.id === "string" ? card.id.trim() : "";
    if (id) keys.add(id.toLowerCase());
  });
  return keys;
};

const resolveSubscriptionAutoImportFrequency = (timestamps = []) => {
  const sorted = (Array.isArray(timestamps) ? timestamps : [])
    .map((value) => normalizeTemporalMs(value, 0))
    .filter((value) => value > 0)
    .sort((a, b) => a - b);
  if (sorted.length < 2) return null;
  const intervals = [];
  for (let index = 1; index < sorted.length; index += 1) {
    const deltaDays = (sorted[index] - sorted[index - 1]) / DAY_MS;
    if (Number.isFinite(deltaDays) && deltaDays > 0.5) intervals.push(deltaDays);
  }
  if (!intervals.length) return null;
  const monthlyHits = intervals.filter((days) => days >= 24 && days <= 38).length;
  const weeklyHits = intervals.filter((days) => days >= 6 && days <= 8.5).length;
  if (monthlyHits >= 1 && sorted.length >= SUBSCRIPTION_AUTO_IMPORT_MIN_MONTHLY_REPEATS) {
    return { frequency: "monthly", confidenceHits: monthlyHits };
  }
  if (weeklyHits >= 2 && sorted.length >= SUBSCRIPTION_AUTO_IMPORT_MIN_WEEKLY_REPEATS) {
    return { frequency: "weekly", confidenceHits: weeklyHits };
  }
  return null;
};

const buildSubscriptionAutoImportCandidates = ({
  historyEvents = [],
  existingCards = [],
  now = Date.now(),
} = {}) => {
  const cutoff = Math.max(0, Number(now) || Date.now()) - SUBSCRIPTION_AUTO_IMPORT_LOOKBACK_MS;
  const existingKeys = getSubscriptionAutoImportExistingKeys(existingCards);
  const groups = new Map();
  (Array.isArray(historyEvents) ? historyEvents : []).forEach((entry) => {
    if (!entry || entry.kind !== "spend") return;
    const timestamp = normalizeTemporalMs(entry.timestamp, 0);
    if (!timestamp || timestamp < cutoff || timestamp > now + DAY_MS) return;
    const meta = entry.meta || {};
    const amountUSD = Math.max(0, Number(meta.amountUSD) || 0);
    if (!Number.isFinite(amountUSD) || amountUSD <= 0.01) return;
    const title = normalizeSubscriptionAutoImportTitle(
      meta.title || meta.templateTitle || meta.template_title || meta.name || ""
    );
    const key = getSubscriptionAutoImportKey(title);
    if (!key || existingKeys.has(key)) return;
    const templateId = typeof meta.templateId === "string" ? meta.templateId.trim() : "";
    if (templateId && existingKeys.has(templateId.toLowerCase())) return;
    const group = groups.get(key) || {
      key,
      title,
      templateIds: new Set(),
      events: [],
    };
    if (templateId) group.templateIds.add(templateId);
    group.events.push({ amountUSD, timestamp });
    groups.set(key, group);
  });
  const candidates = [];
  groups.forEach((group) => {
    const uniqueByDay = new Map();
    group.events.forEach((event) => {
      const dayKey = getDayKey(event.timestamp);
      const current = uniqueByDay.get(dayKey);
      if (!current || event.timestamp > current.timestamp) {
        uniqueByDay.set(dayKey, event);
      }
    });
    const events = Array.from(uniqueByDay.values()).sort((a, b) => a.timestamp - b.timestamp);
    if (events.length < SUBSCRIPTION_AUTO_IMPORT_MIN_MONTHLY_REPEATS) return;
    const amounts = events.map((event) => event.amountUSD).sort((a, b) => a - b);
    const medianAmountUSD = amounts[Math.floor(amounts.length / 2)] || 0;
    if (medianAmountUSD <= 0) return;
    const similarEvents = events.filter((event) => {
      const delta = Math.abs(event.amountUSD - medianAmountUSD);
      return delta <= Math.max(1, medianAmountUSD * SUBSCRIPTION_AUTO_IMPORT_AMOUNT_TOLERANCE);
    });
    const frequencyInfo = resolveSubscriptionAutoImportFrequency(
      similarEvents.map((event) => event.timestamp)
    );
    if (!frequencyInfo) return;
    const lastEvent = similarEvents[similarEvents.length - 1];
    const firstEvent = similarEvents[0];
    const lastDate = new Date(lastEvent.timestamp);
    const monthlyDay = Math.max(1, Math.min(31, lastDate.getDate()));
    const hashedKey = hashSubscriptionAutoImportKey(group.key);
    candidates.push({
      id: `subscription_auto_${hashedKey}`,
      title: group.title,
      amountUSD: medianAmountUSD,
      frequency: frequencyInfo.frequency,
      monthlyDay,
      firstSeenAt: firstEvent.timestamp,
      lastPaidAt: lastEvent.timestamp,
      repeatCount: similarEvents.length,
      sourceTemplateIds: Array.from(group.templateIds),
      confidenceHits: frequencyInfo.confidenceHits,
    });
  });
  return candidates
    .sort((a, b) => {
      if ((b.repeatCount || 0) !== (a.repeatCount || 0)) return (b.repeatCount || 0) - (a.repeatCount || 0);
      return (b.lastPaidAt || 0) - (a.lastPaidAt || 0);
    })
    .slice(0, SUBSCRIPTION_AUTO_IMPORT_MAX_CANDIDATES);
};

const normalizeIncomeEntryType = (value) =>
  value === INCOME_ENTRY_TYPES.EXTRA ? INCOME_ENTRY_TYPES.EXTRA : INCOME_ENTRY_TYPES.MONTHLY;

const normalizeIncomeEntry = (entry) => {
  if (!entry || typeof entry !== "object") return null;
  const amountUSD = Math.max(0, Number(entry.amountUSD) || 0);
  if (!Number.isFinite(amountUSD) || amountUSD <= 0) return null;
  const receivedAt = normalizeTemporalMs(entry.receivedAt, Date.now());
  if (!Number.isFinite(receivedAt)) return null;
  const id =
    typeof entry.id === "string" && entry.id.trim()
      ? entry.id
      : `income_${receivedAt}_${Math.random().toString(16).slice(2, 8)}`;
  const entryType = normalizeIncomeEntryType(entry.entryType);
  const createdAt = normalizeTemporalMs(entry.createdAt, receivedAt);
  const rawPayday = entry.payday ?? entry.incomePayday;
  const payday =
    rawPayday === null || rawPayday === undefined
      ? null
      : normalizeIncomePayday(rawPayday);
  return {
    id,
    amountUSD,
    receivedAt,
    createdAt,
    ...(payday ? { payday } : {}),
    note: typeof entry.note === "string" ? entry.note : "",
    entryType,
  };
};

const normalizeIncomeEntries = (list) => {
  const entries = Array.isArray(list) ? list : [];
  const normalized = entries.map(normalizeIncomeEntry).filter(Boolean);
  normalized.sort((a, b) => (b.receivedAt || 0) - (a.receivedAt || 0));
  return normalized;
};

const resolveIncomeEntryBudgetPeriodKey = (entry, fallbackPayday = DEFAULT_INCOME_PAYDAY) => {
  const receivedAt = normalizeTemporalMs(entry?.receivedAt, 0);
  if (!receivedAt) return "";
  const payday = normalizeIncomePayday(entry?.payday, fallbackPayday);
  return getBudgetPeriodKey(receivedAt, payday);
};

const getIncomeForMonth = (entries, monthKey, options = {}) => {
  if (!monthKey) return 0;
  const entryTypeFilter = options?.entryType;
  const incomePayday = normalizeIncomePayday(options?.payday);
  return (Array.isArray(entries) ? entries : []).reduce((sum, entry) => {
    if (resolveIncomeEntryBudgetPeriodKey(entry, incomePayday) !== monthKey) return sum;
    if (
      entryTypeFilter &&
      normalizeIncomeEntryType(entry?.entryType) !== entryTypeFilter
    ) {
      return sum;
    }
    return sum + Math.max(0, Number(entry.amountUSD) || 0);
  }, 0);
};

const getRecurringIncomeEntryForMonth = (entries, monthKey, options = {}) => {
  if (!monthKey) return 0;
  const incomePayday = normalizeIncomePayday(options?.payday);
  let latestMonthlyEntry = null;
  (Array.isArray(entries) ? entries : []).forEach((entry) => {
    const entryType = normalizeIncomeEntryType(entry?.entryType);
    if (entryType !== INCOME_ENTRY_TYPES.MONTHLY) return;
    const receivedAt = normalizeTemporalMs(entry?.receivedAt, 0);
    if (!receivedAt) return;
    const entryMonthKey = resolveIncomeEntryBudgetPeriodKey(entry, incomePayday);
    if (!entryMonthKey || entryMonthKey > monthKey) return;
    const latestReceivedAt = normalizeTemporalMs(latestMonthlyEntry?.receivedAt, 0);
    if (!latestMonthlyEntry || receivedAt >= latestReceivedAt) {
      latestMonthlyEntry = entry;
    }
  });
  return latestMonthlyEntry;
};

const getRecurringIncomeForMonth = (entries, monthKey, options = {}) => {
  const latestMonthlyEntry = getRecurringIncomeEntryForMonth(entries, monthKey, options);
  return Math.max(0, Number(latestMonthlyEntry?.amountUSD) || 0);
};

const getExtraIncomeForMonth = (entries, monthKey, options = {}) =>
  getIncomeForMonth(entries, monthKey, {
    ...options,
    entryType: INCOME_ENTRY_TYPES.EXTRA,
  });

const getBudgetIncomeForMonth = (entries, monthKey, options = {}) =>
  getRecurringIncomeForMonth(entries, monthKey, options) +
  getExtraIncomeForMonth(entries, monthKey, options);

const resolveBudgetTimeAdjustment = ({
  incomeEntries = [],
  periodKey = "",
  payday = DEFAULT_INCOME_PAYDAY,
  now = Date.now(),
} = {}) => {
  const incomePayday = normalizeIncomePayday(payday);
  const periodInfo = resolveBudgetPeriodInfo({ periodKey, payday: incomePayday, now });
  if (!periodInfo.startAt || !periodInfo.endAt) {
    return { elapsedRatio: 0, remainingRatio: 1, elapsedIncomeUSD: 0 };
  }
  const recurringEntry = getRecurringIncomeEntryForMonth(incomeEntries, periodKey, {
    payday: incomePayday,
  });
  if (!recurringEntry) {
    return { elapsedRatio: 0, remainingRatio: 1, elapsedIncomeUSD: 0 };
  }
  const receivedAt = normalizeTemporalMs(recurringEntry.receivedAt, 0);
  const createdAt = normalizeTemporalMs(recurringEntry.createdAt, receivedAt);
  if (!receivedAt || !createdAt || createdAt <= periodInfo.startAt + DAY_MS * 0.5) {
    return { elapsedRatio: 0, remainingRatio: 1, elapsedIncomeUSD: 0 };
  }
  if (createdAt < periodInfo.startAt || createdAt >= periodInfo.endAt) {
    return { elapsedRatio: 0, remainingRatio: 1, elapsedIncomeUSD: 0 };
  }
  const elapsedCutoff = periodInfo.isCurrentPeriod
    ? Math.min(createdAt, normalizeTemporalMs(now, Date.now()))
    : createdAt;
  const elapsedRatio = clampNumber(
    (elapsedCutoff - periodInfo.startAt) / periodInfo.durationMs,
    0,
    1
  );
  const amountUSD = Math.max(0, Number(recurringEntry.amountUSD) || 0);
  return {
    elapsedRatio,
    remainingRatio: clampNumber(1 - elapsedRatio, 0, 1),
    elapsedIncomeUSD: amountUSD * elapsedRatio,
  };
};

const getNextMonthKey = (monthKey) => {
  const parsed = parseMonthKey(monthKey);
  if (!parsed) return "";
  parsed.setMonth(parsed.getMonth() + 1);
  return getMonthKey(parsed.getTime());
};

const collectBudgetMonthKeys = (
  incomeEntries = [],
  historyEvents = [],
  currentMonthKey = "",
  payday = DEFAULT_INCOME_PAYDAY
) => {
  const incomePayday = normalizeIncomePayday(payday);
  const keys = new Set();
  if (currentMonthKey) {
    keys.add(currentMonthKey);
  }
  let earliestRecurringMonthKey = "";
  (Array.isArray(incomeEntries) ? incomeEntries : []).forEach((entry) => {
    const monthKey = resolveIncomeEntryBudgetPeriodKey(entry, incomePayday);
    if (!monthKey) return;
    keys.add(monthKey);
    const entryType = normalizeIncomeEntryType(entry?.entryType);
    if (entryType === INCOME_ENTRY_TYPES.MONTHLY) {
      if (!earliestRecurringMonthKey || monthKey < earliestRecurringMonthKey) {
        earliestRecurringMonthKey = monthKey;
      }
    }
  });
  (Array.isArray(historyEvents) ? historyEvents : []).forEach((entry) => {
    const timestamp = normalizeTemporalMs(entry?.timestamp, 0);
    if (!timestamp) return;
    const monthKey = getBudgetPeriodKey(timestamp, incomePayday);
    if (monthKey) {
      keys.add(monthKey);
    }
  });
  let latestMonthKey = "";
  keys.forEach((key) => {
    if (!latestMonthKey || key > latestMonthKey) {
      latestMonthKey = key;
    }
  });
  if (
    earliestRecurringMonthKey &&
    latestMonthKey &&
    earliestRecurringMonthKey <= latestMonthKey
  ) {
    let cursor = earliestRecurringMonthKey;
    let guard = 0;
    while (cursor && cursor <= latestMonthKey && guard < 240) {
      keys.add(cursor);
      cursor = getNextMonthKey(cursor);
      guard += 1;
    }
  }
  const list = Array.from(keys).filter(Boolean);
  list.sort((a, b) => (a < b ? 1 : -1));
  return list;
};

const buildBudgetMonthlyStats = ({
  incomeEntries = [],
  historyEvents = [],
  currentMonthKey = "",
  resolveHistoryCategoryId = null,
  incomePayday = DEFAULT_INCOME_PAYDAY,
} = {}) => {
  const payday = normalizeIncomePayday(incomePayday);
  const stats = {};
  const ensure = (key) => {
    if (!key) return null;
    if (!stats[key]) {
      stats[key] = { incomeUSD: 0, spendTotalUSD: 0, spendByCategory: {} };
    }
    return stats[key];
  };
  const monthKeys = collectBudgetMonthKeys(incomeEntries, historyEvents, currentMonthKey, payday);
  monthKeys.forEach((key) => {
    const target = ensure(key);
    if (!target) return;
    target.incomeUSD = getBudgetIncomeForMonth(incomeEntries, key, { payday });
    target.timeAdjustmentUSD = resolveBudgetTimeAdjustment({
      incomeEntries,
      periodKey: key,
      payday,
    }).elapsedIncomeUSD;
  });
  (Array.isArray(historyEvents) ? historyEvents : []).forEach((entry) => {
    if (!entry || entry.kind !== "spend") return;
    const timestamp = normalizeTemporalMs(entry?.timestamp, 0);
    if (!timestamp) return;
    const monthKey = getBudgetPeriodKey(timestamp, payday);
    if (!monthKey) return;
    const amount = Math.max(0, Number(entry?.meta?.amountUSD) || 0);
    if (!amount) return;
    const target = ensure(monthKey);
    if (!target) return;
    target.spendTotalUSD += amount;
    if (typeof resolveHistoryCategoryId === "function") {
      const categoryId = resolveHistoryCategoryId(entry);
      if (categoryId) {
        target.spendByCategory[categoryId] = (target.spendByCategory[categoryId] || 0) + amount;
      }
    }
  });
  return stats;
};

const buildBudgetCarryoverMap = (stats = {}) => {
  const keys = Object.keys(stats || {});
  if (!keys.length) return {};
  const sorted = [...keys].sort();
  let running = 0;
  return sorted.reduce((acc, key) => {
    acc[key] = running;
    const monthStats = stats?.[key] || {};
    running +=
      Math.max(0, Number(monthStats?.incomeUSD) || 0) -
      Math.max(0, Number(monthStats?.timeAdjustmentUSD) || 0) -
      Math.max(0, Number(monthStats?.spendTotalUSD) || 0);
    return acc;
  }, {});
};

const clampNumber = (value, min = 0, max = 1) => Math.min(Math.max(value, min), max);

const deriveSavingStyle = (decisionStats = {}) => {
  const totalDecisions =
    (decisionStats?.resolvedToDeclines || 0) + (decisionStats?.resolvedToWishes || 0);
  if (!totalDecisions) return "balanced";
  const declineShare = (decisionStats?.resolvedToDeclines || 0) / totalDecisions;
  if (declineShare >= 0.7) return "aggressive";
  if (declineShare <= 0.4) return "relaxed";
  return "balanced";
};

const computeSavingsRate = ({ decisionStats, incomeUSD = 0 }) => {
  if (!incomeUSD) return BUDGET_DEFAULT_SAVINGS_RATE;
  const savingStyle = deriveSavingStyle(decisionStats);
  const baseRate =
    savingStyle === "aggressive"
      ? 0.26
      : savingStyle === "relaxed"
      ? 0.12
      : BUDGET_DEFAULT_SAVINGS_RATE;
  return clampNumber(baseRate, BUDGET_MIN_SAVINGS_RATE, BUDGET_MAX_SAVINGS_RATE);
};

