const parseAmountValue = (value) => {
  if (value === null || value === undefined) return 0;
  if (typeof value === "number") return Number.isFinite(value) ? value : 0;
  if (typeof value === "string") {
    const parsed = Number(value.replace(",", "."));
    return Number.isFinite(parsed) ? parsed : 0;
  }
  return 0;
};

const clampTransactionAmountUSD = (value) => {
  const parsed = parseAmountValue(value);
  if (!Number.isFinite(parsed) || parsed <= 0) return 0;
  return Math.min(parsed, MAX_TRANSACTION_AMOUNT_USD);
};

const clampSavedBalanceUSD = (value) => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return 0;
  return Math.min(MAX_SAVED_BALANCE_USD, Math.max(0, parsed));
};

const resolveCustomPriceUSD = (customTemptation, fallbackCurrency = DEFAULT_PROFILE.currency) => {
  const direct = parseAmountValue(customTemptation?.amountUSD);
  if (direct > 0) return direct;
  const local = parseAmountValue(customTemptation?.amount ?? customTemptation?.amountLocal ?? customTemptation?.price);
  if (local > 0) {
    const currencyCode = customTemptation?.currency || fallbackCurrency || DEFAULT_PROFILE.currency;
    return convertFromCurrency(local, currencyCode);
  }
  return 0;
};

