const createCustomTemptationCard = (customTemptation, fallbackCurrency = DEFAULT_PROFILE.currency, gender = "none") => {
  const price = resolveCustomPriceUSD(customTemptation, fallbackCurrency) || CUSTOM_TEMPTATION_SAMPLE_USD;
  const createdAt = Number.isFinite(Number(customTemptation?.createdAt)) ? Number(customTemptation.createdAt) : null;
  const precision =
    typeof customTemptation?.pricePrecision === "number" && Number.isFinite(customTemptation.pricePrecision)
      ? Math.max(0, Math.min(6, customTemptation.pricePrecision))
      : null;
  let frequency = normalizeFrequencyId(customTemptation?.frequency) || null;
  let frequencyCustom =
    normalizeCustomFrequency(customTemptation?.frequencyCustom || customTemptation?.customFrequency) || null;
  if (frequency === "biweekly") {
    frequency = "custom";
    frequencyCustom = { ...DEFAULT_CUSTOM_FREQUENCY };
  }
  if (frequency === "custom" && !frequencyCustom) {
    frequencyCustom = { ...DEFAULT_CUSTOM_FREQUENCY };
  }
  const frequencyIntervalMs = frequency === "custom" ? getCustomFrequencyIntervalMs(frequencyCustom) : null;
  const reminderTime =
    normalizeFrequencyReminderTime({
      hour: customTemptation?.frequencyReminderHour,
      minute: customTemptation?.frequencyReminderMinute,
    }) || {
      hour: DEFAULT_FREQUENCY_REMINDER_HOUR,
      minute: DEFAULT_FREQUENCY_REMINDER_MINUTE,
    };
  const weeklyDays = normalizeFrequencyWeeklyDays(
    customTemptation?.frequencyWeeklyDays ?? customTemptation?.frequencyWeeklyDay
  ) || [...DEFAULT_FREQUENCY_WEEKLY_DAYS];
  const monthlyDays = normalizeFrequencyMonthlyDays(
    customTemptation?.frequencyMonthlyDays ?? customTemptation?.frequencyMonthlyDay
  ) || [...DEFAULT_FREQUENCY_MONTHLY_DAYS];
  const resolvedTitle = customTemptation?.title;
  const title =
    resolvedTitle && resolvedTitle.trim().length
      ? resolvedTitle.trim()
      : CUSTOM_HABIT_FALLBACK_TITLES.en;
  const description = buildCustomTemptationDescription(gender);
  const impulseCategory =
    customTemptation?.impulseCategory && IMPULSE_CATEGORY_DEFS[customTemptation.impulseCategory]
      ? customTemptation.impulseCategory
      : null;
  const categories = ["habit", "custom"];
  if (impulseCategory) {
    categories.push(impulseCategory);
  }
  return {
    id: customTemptation.id || "custom_habit",
    emoji: customTemptation.emoji || "💡",
    color: "#FFF5E6",
    categories,
    basePriceUSD: price,
    priceUSD: price,
    pricePrecision: precision,
    createdAt: createdAt || null,
    frequency: frequency || null,
    frequencyCustom: frequency === "custom" ? frequencyCustom || null : null,
    frequencyIntervalMs: frequency === "custom" ? frequencyIntervalMs || null : null,
    frequencyReminderHour: reminderTime.hour,
    frequencyReminderMinute: reminderTime.minute,
    frequencyWeeklyDay: weeklyDays[0] ?? DEFAULT_FREQUENCY_WEEKLY_DAY,
    frequencyMonthlyDay: monthlyDays[0] ?? DEFAULT_FREQUENCY_MONTHLY_DAY,
    frequencyWeeklyDays: weeklyDays,
    frequencyMonthlyDays: monthlyDays,
    frequencyReminderManualConfigured: customTemptation?.frequencyReminderManualConfigured === true,
    title: {
      ru: resolvedTitle || CUSTOM_HABIT_FALLBACK_TITLES.ru,
      en: title || CUSTOM_HABIT_FALLBACK_TITLES.en,
      es: resolvedTitle || CUSTOM_HABIT_FALLBACK_TITLES.es,
      fr: resolvedTitle || CUSTOM_HABIT_FALLBACK_TITLES.fr,
    },
    description,
    impulseCategoryOverride: impulseCategory,
  };
};

const buildDuplicateTemptationTitle = (sourceTitle, existingTitles = []) => {
  const normalizedSource = String(sourceTitle || "").trim();
  if (!normalizedSource) return "2";
  const normalizedExisting = new Set(
    (Array.isArray(existingTitles) ? existingTitles : [])
      .map((title) => String(title || "").trim().toLocaleLowerCase())
      .filter(Boolean)
  );
  const trailingNumberMatch = normalizedSource.match(/^(.*\S)\s+(\d+)$/u);
  const trailingNumber = trailingNumberMatch ? Number(trailingNumberMatch[2]) : null;
  const potentialBase = trailingNumberMatch ? trailingNumberMatch[1].trim() : normalizedSource;
  const hasGeneratedBase =
    trailingNumber !== null &&
    trailingNumber >= 2 &&
    normalizedExisting.has(potentialBase.toLocaleLowerCase());
  const baseTitle = hasGeneratedBase ? potentialBase : normalizedSource;
  let suffix = hasGeneratedBase ? trailingNumber + 1 : 2;
  while (normalizedExisting.has(`${baseTitle} ${suffix}`.toLocaleLowerCase())) {
    suffix += 1;
  }
  return `${baseTitle} ${suffix}`;
};

const hasValidCustomPrice = (entry) => {
  if (!entry || typeof entry !== "object") return false;
  const price = Number(entry.priceUSD);
  if (Number.isFinite(price) && price > 0) return true;
  const basePrice = Number(entry.basePriceUSD);
  return Number.isFinite(basePrice) && basePrice > 0;
};

const normalizeCustomTemptationEntry = (
  entry,
  fallbackCurrency = DEFAULT_PROFILE.currency
) => {
  if (!entry || typeof entry !== "object") return null;
  const genderValue = entry?.gender || "none";
  if (hasValidCustomPrice(entry)) {
    const entryCategory =
      entry.impulseCategoryOverride || entry.impulseCategory || null;
    const normalizedCategory =
      entryCategory && IMPULSE_CATEGORY_DEFS[entryCategory] ? entryCategory : null;
    return {
      ...entry,
      description: buildCustomTemptationDescription(genderValue),
      impulseCategoryOverride: normalizedCategory,
      quickTemptation: true,
    };
  }
  const rebuilt = createCustomTemptationCard(entry, fallbackCurrency, genderValue);
  if (!rebuilt) return null;
  const merged = { ...rebuilt, ...entry };
  merged.priceUSD = rebuilt.priceUSD;
  merged.basePriceUSD = rebuilt.basePriceUSD;
  merged.description = rebuilt.description;
  const entryCategory =
    entry.impulseCategoryOverride || entry.impulseCategory || rebuilt.impulseCategoryOverride;
  merged.impulseCategoryOverride =
    entryCategory && IMPULSE_CATEGORY_DEFS[entryCategory] ? entryCategory : rebuilt.impulseCategoryOverride || null;
  merged.quickTemptation = true;
  return merged;
};

