const getPersonaFeedStrategy = (personaId) =>
  PERSONA_FEED_STRATEGY[personaId] || PERSONA_FEED_STRATEGY.mindful_coffee;

const buildFeedCategoryWeightMap = (categories = []) => {
  const map = new Map();
  categories.forEach((category, index) => {
    if (!category) return;
    map.set(category, Math.max(22 - index * 4, 8));
  });
  return map;
};

const buildFeedIdWeightMap = (ids = []) => {
  const map = new Map();
  ids.forEach((id, index) => {
    if (!id || map.has(id)) return;
    map.set(id, Math.max(70 - index * 5, 18));
  });
  return map;
};

const scoreTemptationForFeed = (
  card,
  { idWeightMap = new Map(), categoryWeightMap = new Map(), popularIdSet = new Set() } = {}
) => {
  if (!card) return Number.NEGATIVE_INFINITY;
  let score = 0;
  const cardId = typeof card.id === "string" ? card.id : "";
  if (idWeightMap.has(cardId)) {
    score += idWeightMap.get(cardId) || 0;
  }
  if (popularIdSet.has(cardId)) {
    score += 20;
  }
  const categories = Array.isArray(card.categories) ? card.categories : [];
  categories.forEach((category) => {
    score += categoryWeightMap.get(category) || 0;
  });
  if (categories.includes("habit")) {
    score += 4;
  }
  const price = getTemptationPrice(card);
  if (Number.isFinite(price) && price > 0) {
    if (price <= 20) {
      score += 14;
    } else if (price <= 60) {
      score += 9;
    } else if (price <= 180) {
      score += 4;
    } else if (price >= 2500) {
      score -= 10;
    }
  }
  return score;
};

const matchesGenderAudience = (card, gender = "none") => {
  if (!card || !card.audience || !gender || gender === "none") return true;
  const list = Array.isArray(card.audience) ? card.audience : [card.audience];
  return list.includes(gender);
};

const buildPersonalizedTemptations = (profile, baseList = DEFAULT_TEMPTATIONS) => {
  const preset = getPersonaPreset(profile?.persona);
  const feedStrategy = getPersonaFeedStrategy(preset?.id);
  const personaExtras = PERSONA_TEMPTATION_PRESETS[preset?.id] || [];
  const personaCard = createPersonaTemptation(preset);
  const rankedIds = [...(feedStrategy?.highlightIds || []), ...UNIVERSAL_POPULAR_FEED_IDS];
  const dedupedRankedIds = [];
  const rankedIdSet = new Set();
  rankedIds.forEach((id) => {
    if (!id || rankedIdSet.has(id)) return;
    rankedIdSet.add(id);
    dedupedRankedIds.push(id);
  });
  const popularIdSet = new Set(UNIVERSAL_POPULAR_FEED_IDS);
  const idWeightMap = buildFeedIdWeightMap(dedupedRankedIds);
  const categoryWeightMap = buildFeedCategoryWeightMap(feedStrategy?.preferredCategories || []);
  const gender = profile?.gender || "none";
  const blockedBaseIds = new Set();
  const seen = new Set();
  const result = [];
  const pushIfVisible = (card) => {
    if (!card || seen.has(card.id)) return;
    if (!matchesGenderAudience(card, gender)) return;
    seen.add(card.id);
    result.push(card);
  };
  const scoreCard = (card) =>
    scoreTemptationForFeed(card, {
      idWeightMap,
      categoryWeightMap,
      popularIdSet,
    });

  // Карта персоны идёт первой, если её не дублирует базовая кофейная карточка.
  const hasBaseCoffee = baseList.some((item) => item?.id === "coffee_to_go");
  const personaHasCoffee =
    preset?.id === "mindful_coffee" ||
    (personaCard && Array.isArray(personaCard.categories) && personaCard.categories.includes("coffee"));
  const shouldSkipPersona = hasBaseCoffee && personaHasCoffee;
  if (!shouldSkipPersona) {
    pushIfVisible(personaCard);
  }
  const sortedPersonaExtras = personaExtras
    .filter((card) => matchesGenderAudience(card, gender))
    .sort((a, b) => {
      const scoreDiff = scoreCard(b) - scoreCard(a);
      if (scoreDiff !== 0) return scoreDiff;
      return getTemptationPrice(a) - getTemptationPrice(b);
    });
  sortedPersonaExtras.forEach((card) => pushIfVisible(card));
  // Подмешиваем профильные и универсально популярные карточки в фиксированном приоритете.
  dedupedRankedIds.forEach((id) => {
    if (blockedBaseIds.has(id)) return;
    const card = baseList.find((item) => item?.id === id);
    pushIfVisible(card);
  });

  // Остальные карточки ранжируем по совпадению с персоной, затем по цене.
  const pool = [...baseList].filter((item) => item && !seen.has(item.id) && !blockedBaseIds.has(item.id));
  const sortedPool = pool
    .filter((item) => matchesGenderAudience(item, gender))
    .sort((a, b) => {
      const scoreDiff = scoreCard(b) - scoreCard(a);
      if (scoreDiff !== 0) return scoreDiff;
      const priceA = getTemptationPrice(a);
      const priceB = getTemptationPrice(b);
      return priceA - priceB;
    });
  return [...result, ...sortedPool];
};

const mergeInteractionStatMaps = (base = {}, incoming = {}) => {
  const result = { ...(base || {}) };
  Object.entries(incoming || {}).forEach(([templateId, stats]) => {
    if (!stats) return;
    const current = result[templateId] || {};
    const merged = { ...current };
    const statsReminderHour = Number(stats.frequencyReminderHour);
    const statsReminderMinute = Number(stats.frequencyReminderMinute);
    const normalizedReminderHour =
      Number.isFinite(statsReminderHour) && statsReminderHour >= 0 && statsReminderHour <= 23
        ? Math.round(statsReminderHour)
        : null;
    const normalizedReminderMinute =
      Number.isFinite(statsReminderMinute) && statsReminderMinute >= 0 && statsReminderMinute <= 59
        ? Math.round(statsReminderMinute)
        : null;
    const normalizedWeeklyDays = normalizeFrequencyWeeklyDays(
      stats.frequencyWeeklyDays ?? stats.frequencyWeeklyDay
    );
    const normalizedMonthlyDays = normalizeFrequencyMonthlyDays(
      stats.frequencyMonthlyDays ?? stats.frequencyMonthlyDay
    );
    const normalizedWeeklyDay = normalizedWeeklyDays?.[0] ?? null;
    const normalizedMonthlyDay = normalizedMonthlyDays?.[0] ?? null;
    merged.saveCount = (current.saveCount || 0) + (stats.saveCount || 0);
    merged.spendCount = (current.spendCount || 0) + (stats.spendCount || 0);
    merged.lastInteractionAt = Math.max(current.lastInteractionAt || 0, stats.lastInteractionAt || 0);
    const latestIsIncoming = (stats.lastInteractionAt || 0) >= (current.lastInteractionAt || 0);
    if (latestIsIncoming) {
      merged.previousInteractionAt = stats.previousInteractionAt || merged.previousInteractionAt || null;
      merged.secondPreviousInteractionAt =
        stats.secondPreviousInteractionAt ?? merged.secondPreviousInteractionAt ?? null;
      merged.detectedIntervalMs = stats.detectedIntervalMs ?? merged.detectedIntervalMs ?? null;
      merged.frequency = stats.frequency ?? merged.frequency ?? null;
      merged.frequencyCustom = stats.frequencyCustom ?? merged.frequencyCustom ?? null;
      merged.intervalMs = stats.intervalMs ?? merged.intervalMs ?? null;
      merged.nextCheckAt = stats.nextCheckAt ?? merged.nextCheckAt ?? null;
      merged.lastTimerResetAt = stats.lastTimerResetAt ?? merged.lastTimerResetAt ?? null;
      merged.firstTimerConfiguredAt =
        stats.firstTimerConfiguredAt ?? merged.firstTimerConfiguredAt ?? null;
      merged.frequencyReminderId = stats.frequencyReminderId ?? merged.frequencyReminderId ?? null;
      merged.frequencyReminderIds = Array.isArray(stats.frequencyReminderIds)
        ? [...stats.frequencyReminderIds]
        : Array.isArray(merged.frequencyReminderIds)
        ? merged.frequencyReminderIds
        : [];
      merged.frequencyReminderScheduledAt =
        stats.frequencyReminderScheduledAt ?? merged.frequencyReminderScheduledAt ?? null;
      merged.frequencyReminderLocale =
        stats.frequencyReminderLocale ?? merged.frequencyReminderLocale ?? null;
      merged.frequencyReminderPlanKey =
        stats.frequencyReminderPlanKey ?? merged.frequencyReminderPlanKey ?? null;
      merged.frequencyReminderHour =
        normalizedReminderHour ?? merged.frequencyReminderHour ?? null;
      merged.frequencyReminderMinute =
        normalizedReminderMinute ?? merged.frequencyReminderMinute ?? null;
      merged.frequencyWeeklyDay = normalizedWeeklyDay ?? merged.frequencyWeeklyDay ?? null;
      merged.frequencyMonthlyDay = normalizedMonthlyDay ?? merged.frequencyMonthlyDay ?? null;
      merged.frequencyWeeklyDays =
        normalizedWeeklyDays ??
        normalizeFrequencyWeeklyDays(merged.frequencyWeeklyDays ?? merged.frequencyWeeklyDay) ??
        [];
      merged.frequencyMonthlyDays =
        normalizedMonthlyDays ??
        normalizeFrequencyMonthlyDays(merged.frequencyMonthlyDays ?? merged.frequencyMonthlyDay) ??
        [];
      merged.frequencyReminderPromptShown =
        stats.frequencyReminderPromptShown === true ||
        merged.frequencyReminderPromptShown === true;
      merged.frequencyReminderManualConfigured =
        stats.frequencyReminderManualConfigured === true ||
        merged.frequencyReminderManualConfigured === true;
      merged.templateTitle = stats.templateTitle ?? merged.templateTitle ?? null;
    } else {
      if (!merged.previousInteractionAt && stats.previousInteractionAt) {
        merged.previousInteractionAt = stats.previousInteractionAt;
      }
      if (!merged.secondPreviousInteractionAt && stats.secondPreviousInteractionAt) {
        merged.secondPreviousInteractionAt = stats.secondPreviousInteractionAt;
      }
    }
    merged.missedCycles = (current.missedCycles || 0) + (stats.missedCycles || 0);
    if (!merged.templateTitle && stats.templateTitle) {
      merged.templateTitle = stats.templateTitle;
    }
    if (!merged.frequencyReminderIds && Array.isArray(stats.frequencyReminderIds)) {
      merged.frequencyReminderIds = [...stats.frequencyReminderIds];
    }
    if (!merged.frequencyReminderPlanKey && stats.frequencyReminderPlanKey) {
      merged.frequencyReminderPlanKey = stats.frequencyReminderPlanKey;
    }
    if (
      merged.frequencyReminderHour == null &&
      Number.isFinite(normalizedReminderHour)
    ) {
      merged.frequencyReminderHour = normalizedReminderHour;
    }
    if (
      merged.frequencyReminderMinute == null &&
      Number.isFinite(normalizedReminderMinute)
    ) {
      merged.frequencyReminderMinute = normalizedReminderMinute;
    }
    if (merged.frequencyWeeklyDay == null && Number.isFinite(normalizedWeeklyDay)) {
      merged.frequencyWeeklyDay = normalizedWeeklyDay;
    }
    if (merged.frequencyMonthlyDay == null && Number.isFinite(normalizedMonthlyDay)) {
      merged.frequencyMonthlyDay = normalizedMonthlyDay;
    }
    if (!Array.isArray(merged.frequencyWeeklyDays) || !merged.frequencyWeeklyDays.length) {
      merged.frequencyWeeklyDays =
        normalizedWeeklyDays ??
        normalizeFrequencyWeeklyDays(merged.frequencyWeeklyDays ?? merged.frequencyWeeklyDay) ??
        [];
    }
    if (!Array.isArray(merged.frequencyMonthlyDays) || !merged.frequencyMonthlyDays.length) {
      merged.frequencyMonthlyDays =
        normalizedMonthlyDays ??
        normalizeFrequencyMonthlyDays(merged.frequencyMonthlyDays ?? merged.frequencyMonthlyDay) ??
        [];
    }
    if (
      merged.frequencyWeeklyDay == null &&
      Array.isArray(merged.frequencyWeeklyDays) &&
      merged.frequencyWeeklyDays.length
    ) {
      merged.frequencyWeeklyDay = merged.frequencyWeeklyDays[0];
    }
    if (
      merged.frequencyMonthlyDay == null &&
      Array.isArray(merged.frequencyMonthlyDays) &&
      merged.frequencyMonthlyDays.length
    ) {
      merged.frequencyMonthlyDay = merged.frequencyMonthlyDays[0];
    }
    if (stats.frequencyReminderPromptShown === true) {
      merged.frequencyReminderPromptShown = true;
    }
    if (stats.frequencyReminderManualConfigured === true) {
      merged.frequencyReminderManualConfigured = true;
    }
    result[templateId] = merged;
  });
  return result;
};

const normalizeFeedCategoryFilterUsage = (value = {}) => {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return Object.entries(source).reduce((acc, [categoryId, stats]) => {
    const id = typeof categoryId === "string" ? categoryId.trim() : "";
    if (!id || id === "all") return acc;
    const rawStats = stats && typeof stats === "object" ? stats : { count: stats };
    const count = Math.max(0, Math.floor(Number(rawStats.count) || 0));
    const lastUsedAt = Math.max(
      0,
      Math.floor(Number(rawStats.lastUsedAt ?? rawStats.lastSelectedAt ?? rawStats.updatedAt) || 0)
    );
    if (count <= 0 && lastUsedAt <= 0) return acc;
    acc[id] = { count, lastUsedAt };
    return acc;
  }, {});
};

const mergeFeedCategoryFilterUsage = (base = {}, incoming = {}) => {
  const result = { ...normalizeFeedCategoryFilterUsage(base) };
  Object.entries(normalizeFeedCategoryFilterUsage(incoming)).forEach(([categoryId, stats]) => {
    const current = result[categoryId] || { count: 0, lastUsedAt: 0 };
    result[categoryId] = {
      count: (Number(current.count) || 0) + (Number(stats.count) || 0),
      lastUsedAt: Math.max(Number(current.lastUsedAt) || 0, Number(stats.lastUsedAt) || 0),
    };
  });
  return result;
};

const useFadeIn = () => {
  const fade = useRef(new Animated.Value(Platform.OS === "android" ? 1 : 0)).current;
  useEffect(() => {
    if (Platform.OS === "android") {
      fade.stopAnimation?.();
      fade.setValue(1);
      return;
    }
    fade.setValue(0);
    Animated.spring(fade, {
      toValue: 1,
      tension: 130,
      friction: 16,
      useNativeDriver: true,
    }).start();
  }, [fade]);
  return fade;
};

const useOnboardingStaggerValues = (count, { delay = 90 } = {}) => {
  const valuesRef = useRef([]);
  const normalizedCount = Math.max(0, Number(count) || 0);
  if (valuesRef.current.length !== normalizedCount) {
    const initialValue = Platform.OS === "android" ? 1 : 0;
    valuesRef.current = Array.from({ length: normalizedCount }).map(
      () => new Animated.Value(initialValue)
    );
  }
  useEffect(() => {
    if (!valuesRef.current.length) return undefined;
    if (Platform.OS === "android") {
      valuesRef.current.forEach((value) => {
        value.stopAnimation?.();
        value.setValue(1);
      });
      return undefined;
    }
    valuesRef.current.forEach((value) => value.setValue(0));
    const animation = Animated.stagger(
      Math.max(24, delay),
      valuesRef.current.map((value) =>
        Animated.spring(value, {
          toValue: 1,
          speed: 16,
          bounciness: 7,
          useNativeDriver: true,
        })
      )
    );
    animation.start();
    return () => animation.stop();
  }, [normalizedCount, delay]);
  return valuesRef.current;
};

