  const categoryBudgetLabel = categoryBudget?.label || t("defaultSpendLabel");
  const categoryBudgetTitle = hasCategoryBudgetLimit
    ? `${t("spendPreviewCategoryRemainingLabel")}: ${categoryBudgetLabel}`
    : `${categoryBudgetLabel} · ${t("spendPreviewNoLimitHint")}`;
  const categoryBudgetHint = hasCategoryBudgetLimit
    ? amountSliderIsSpendMode
      ? `${categoryBudgetRemainingBeforeLabel} → ${categoryBudgetRemainingAfterLabel} · ${categoryBudgetSpentAfterLabel} / ${categoryBudgetLimitLabel}`
      : `${t("budgetRemainingLabel")}: ${categoryBudgetRemainingBeforeLabel} → ${categoryBudgetRemainingAfterLabel}`
    : amountSliderIsSpendMode
    ? `${t("spendPreviewLimitDropLabel")}: -${amountSliderCurrentLabel}`
    : `${t("homeWidgetSavedMonthLabel")}: +${amountSliderCurrentLabel}`;
  const categoryBudgetImpactLabel = amountSliderIsSpendMode
    ? `-${amountSliderCurrentLabel}`
    : `+${amountSliderCurrentLabel}`;
  const categoryBudgetFillWidth = `${Math.max(0, Math.min(100, categoryBudgetRemainingRatio * 100))}%`;
  const amountSliderMoodIntensity = Math.max(0, Math.min(1, amountSliderValue));
  const amountSliderMoodAuraColor = resolveAndroidOpaqueLayerColor(
    colorWithAlpha(
      amountSliderIsSpendMode ? cardSpendActionColor : cardSaveActionColor,
      amountSliderIsSpendMode
        ? 0.12 + amountSliderMoodIntensity * 0.12
        : 0.18 + amountSliderMoodIntensity * 0.14
    ),
    amountSliderMoodStageColor
  );
  const amountSliderProjectionColor = amountSliderIsSpendMode
    ? blendColors(colors.text, cardSpendActionColor, Math.min(0.82, 0.22 + amountSliderMoodIntensity * 0.68))
    : blendColors(colors.text, cardSaveActionColor, Math.min(0.78, 0.2 + amountSliderMoodIntensity * 0.62));
  const amountSliderProjectionValueStyle = {
    color: amountSliderProjectionColor,
    fontSize: Math.round(27 + amountSliderMoodIntensity * 8),
    lineHeight: Math.round(32 + amountSliderMoodIntensity * 8),
  };
  const amountSliderCatSource = amountSliderIsSpendMode
    ? amountSliderMoodIntensity > 0.72
      ? CLASSIC_TAMAGOTCHI_ANIMATIONS.cry
      : CLASSIC_TAMAGOTCHI_ANIMATIONS.sad
    : amountSliderMoodIntensity > 0.52
    ? CLASSIC_TAMAGOTCHI_ANIMATIONS.happyHeadshake
    : CLASSIC_TAMAGOTCHI_ANIMATIONS.happy;
  const amountSliderCatMoodStyle = {
    opacity: amountSliderIsSpendMode
      ? Math.max(0.72, 1 - amountSliderMoodIntensity * 0.16)
      : 1,
    transform: [
      { translateY: amountSliderIsSpendMode ? amountSliderMoodIntensity * 8 : -amountSliderMoodIntensity * 4 },
      { scale: amountSliderIsSpendMode ? 1 - amountSliderMoodIntensity * 0.07 : 0.96 + amountSliderMoodIntensity * 0.08 },
      { rotate: amountSliderIsSpendMode ? `${amountSliderMoodIntensity * -5}deg` : `${amountSliderMoodIntensity * 3}deg` },
    ],
  };
  const amountSliderStepCount = 24;
  const amountSliderHapticCooldownMs = 40;

  const markAmountSliderInteracted = useCallback(() => {
    if (amountSliderInteractedRef.current) return;
    amountSliderInteractedRef.current = true;
    setAmountSliderInteracted(true);
  }, []);

  const updateAmountSliderValue = useCallback(
    (nextValue, { fromUser = false, force = false } = {}) => {
      const clamped = Math.max(0, Math.min(1, Number.isFinite(nextValue) ? nextValue : 0));
      amountSliderValueRef.current = clamped;
      if (fromUser) {
        amountSliderManualUSDRef.current = null;
        markAmountSliderInteracted();
        const stepIndex = Math.round(clamped * amountSliderStepCount);
        if (stepIndex !== amountSliderStepRef.current) {
          amountSliderStepRef.current = stepIndex;
          const now = Date.now();
          if (now - amountSliderHapticCooldownRef.current > amountSliderHapticCooldownMs) {
            triggerSelectionHaptic();
            playSound?.("counter", { skipCooldown: true });
            amountSliderHapticCooldownRef.current = now;
          }
        }
      }
      if (force) {
        if (amountSliderRafRef.current) {
          cancelAnimationFrame(amountSliderRafRef.current);
          amountSliderRafRef.current = null;
        }
        amountSliderPendingValueRef.current = null;
        setAmountSliderValue(clamped);
        return clamped;
      }
      amountSliderPendingValueRef.current = clamped;
      if (amountSliderRafRef.current) {
        return clamped;
      }
      amountSliderRafRef.current = requestAnimationFrame(() => {
        amountSliderRafRef.current = null;
        const pending = amountSliderPendingValueRef.current;
        if (pending === null || pending === undefined) return;
        amountSliderPendingValueRef.current = null;
        setAmountSliderValue(pending);
      });
      return clamped;
    },
    [
      amountSliderHapticCooldownMs,
      amountSliderStepCount,
      markAmountSliderInteracted,
      playSound,
    ]
  );

  const notifyAmountSliderTouch = useCallback(
    (isTouching) => {
      if (typeof onAmountSliderToggle !== "function") return;
      onAmountSliderToggle(Boolean(isTouching), item?.id || null);
    },
    [item?.id, onAmountSliderToggle]
  );

  const openAmountSlider = useCallback(
    (actionType) => {
      if (cardLocked) {
        onLockedPress?.(item);
        return;
      }
      if (showEditorInline) return;
      runLayoutAnimation();
      setAmountSliderAction(actionType);
      setAmountSliderVisible(true);
      amountSliderInteractedRef.current = false;
      setAmountSliderInteracted(false);
      amountSliderBaseOverrideUSDRef.current = null;
      amountSliderManualUSDRef.current = null;
      setAmountSliderBaseOverrideUSD(null);
      setAmountManualVisible(false);
      setAmountManualValue("");
      setAmountManualError("");
      amountSliderStepRef.current = Math.round(0.5 * amountSliderStepCount);
      amountSliderHapticCooldownRef.current = 0;
      updateAmountSliderValue(0.5, { fromUser: false });
      triggerHaptic(Haptics.ImpactFeedbackStyle.Light);
      playSound?.("tap", { skipCooldown: true });
    },
    [
      cardLocked,
      amountSliderStepCount,
      item,
      onLockedPress,
      playSound,
      showEditorInline,
      updateAmountSliderValue,
    ]
  );

  const closeAmountSlider = useCallback(() => {
    if (!amountSliderVisible) return;
    runLayoutAnimation();
    setAmountSliderVisible(false);
    setAmountSliderAction(null);
    amountSliderInteractedRef.current = false;
    setAmountSliderInteracted(false);
    setAmountSliderDragging(false);
    amountSliderBaseOverrideUSDRef.current = null;
    amountSliderManualUSDRef.current = null;
    setAmountSliderBaseOverrideUSD(null);
    setAmountManualVisible(false);
    setAmountManualError("");
    notifyAmountSliderTouch(false);
    if (amountSliderRafRef.current) {
      cancelAnimationFrame(amountSliderRafRef.current);
      amountSliderRafRef.current = null;
    }
    amountSliderPendingValueRef.current = null;
  }, [amountSliderVisible, notifyAmountSliderTouch]);

  useEffect(() => {
    if (!amountSliderVisible) return;
    amountSliderTrackWidthRef.current = amountSliderTrackWidth;
  }, [amountSliderTrackWidth, amountSliderVisible]);

  useEffect(() => {
    if (!showEditorInline && !isEditing) return;
    if (!amountSliderVisible) return;
    closeAmountSlider();
  }, [amountSliderVisible, closeAmountSlider, isEditing, showEditorInline]);
  useEffect(() => {
    if (!pauseFreezeVisible) return;
    if (!showEditorInline && !isEditing) return;
    pauseFreezeAnim.stopAnimation();
    pauseFreezeAnim.setValue(0);
    setPauseFreezeVisible(false);
  }, [isEditing, pauseFreezeAnim, pauseFreezeVisible, showEditorInline]);
  useEffect(() => {
    if (!cardLocked) return;
    if (!amountSliderVisible) return;
    closeAmountSlider();
  }, [amountSliderVisible, cardLocked, closeAmountSlider]);
  useEffect(() => {
    if (!cardLocked) return;
    if (!pauseFreezeVisible) return;
    pauseFreezeAnim.stopAnimation();
    pauseFreezeAnim.setValue(0);
    setPauseFreezeVisible(false);
  }, [cardLocked, pauseFreezeAnim, pauseFreezeVisible]);

  useEffect(() => {
    if (!amountSliderVisible) return;
    amountSliderValueRef.current = 0.5;
    amountSliderStepRef.current = Math.round(0.5 * amountSliderStepCount);
    setAmountSliderValue(0.5);
  }, [amountSliderStepCount, amountSliderVisible, item.id]);

  useEffect(() => {
    return () => {
      notifyAmountSliderTouch(false);
    };
  }, [notifyAmountSliderTouch]);

  useEffect(() => {
    return () => {
      if (amountSliderRafRef.current) {
        cancelAnimationFrame(amountSliderRafRef.current);
        amountSliderRafRef.current = null;
      }
      pauseFreezeAnim.stopAnimation();
      pauseFreezeSelectionPulse.stopAnimation();
    };
  }, [pauseFreezeAnim, pauseFreezeSelectionPulse]);

  const commitAmountSliderTrackLayout = useCallback((width, pageX) => {
    const nextWidth = Number(width) || 0;
    if (nextWidth > 0 && Math.abs(amountSliderTrackWidthRef.current - nextWidth) > 0.5) {
      amountSliderTrackWidthRef.current = nextWidth;
      setAmountSliderTrackWidth(nextWidth);
    }
    if (Number.isFinite(pageX)) {
      amountSliderTrackPageXRef.current = pageX;
    }
  }, []);

  const measureAmountSliderTrack = useCallback(() => {
    const trackNode = amountSliderTrackRef.current;
    if (!trackNode?.measureInWindow) return;
    trackNode.measureInWindow((x, _y, width) => {
      commitAmountSliderTrackLayout(width, x);
    });
  }, [commitAmountSliderTrackLayout]);

  const handleAmountSliderTrackLayout = useCallback(
    (event) => {
      const width = Number(event?.nativeEvent?.layout?.width) || 0;
      commitAmountSliderTrackLayout(width, amountSliderTrackPageXRef.current);
      requestAnimationFrame(() => {
        measureAmountSliderTrack();
      });
    },
    [commitAmountSliderTrackLayout, measureAmountSliderTrack]
  );

  useEffect(() => {
    if (!amountSliderVisible) return;
    requestAnimationFrame(() => {
      measureAmountSliderTrack();
    });
  }, [amountSliderVisible, measureAmountSliderTrack]);

  const openAmountManual = useCallback(() => {
    if (!allowAmountManualInput) return;
    const precision = getCurrencyPrecision(currency);
    const formatted = formatNumberInputValue(amountSliderLocalValue, precision);
    setAmountManualValue(formatted);
    setAmountManualError("");
    setAmountManualVisible(true);
    triggerSelectionHaptic();
    playSound?.("tap", { skipCooldown: true });
  }, [allowAmountManualInput, amountSliderLocalValue, currency, playSound]);

  const closeAmountManual = useCallback(() => {
    setAmountManualVisible(false);
    setAmountManualError("");
  }, []);

  const closePauseFreezePicker = useCallback(
    ({ immediate = false, onClosed = null } = {}) => {
      const notifyClosed = () => {
        if (typeof onClosed === "function") {
          requestAnimationFrame(() => {
            onClosed();
          });
        }
      };
      if (!pauseFreezeVisible) {
        if (immediate) {
          pauseFreezeAnim.stopAnimation();
          pauseFreezeAnim.setValue(0);
        }
        notifyClosed();
        return;
      }
      if (immediate) {
        pauseFreezeAnim.stopAnimation();
        pauseFreezeAnim.setValue(0);
        setPauseFreezeVisible(false);
        notifyClosed();
        return;
      }
      pauseFreezeAnim.stopAnimation();
      Animated.timing(pauseFreezeAnim, {
        toValue: 0,
        duration: 180,
        easing: Easing.inOut(Easing.quad),
        useNativeDriver: true,
      }).start(() => {
        setPauseFreezeVisible(false);
        notifyClosed();
      });
    },
    [pauseFreezeAnim, pauseFreezeVisible]
  );

  const openPauseFreezePicker = useCallback(() => {
    if (cardLocked) {
      onLockedPress?.(item);
      return;
    }
    if (!allowThinkAction) {
      onAction?.("pause", item, {
        freezeDurationMs: DEFAULT_TEMPTATION_PAUSE_FREEZE_DURATION_MS,
        freezeOptionId: DEFAULT_TEMPTATION_PAUSE_OPTION_ID,
      });
      return;
    }
    if (showEditorInline) return;
    if (amountSliderVisible) {
      closeAmountSlider();
    }
    const defaultOption =
      pauseFreezeOptions.find((option) => option.id === DEFAULT_TEMPTATION_PAUSE_OPTION_ID) ||
      pauseFreezeOptions[0];
    if (defaultOption?.id) {
      setPauseFreezeOptionId(defaultOption.id);
    }
    setPauseFreezeVisible(true);
    triggerSelectionHaptic();
    playSound?.("tap", { skipCooldown: true });
  }, [
    amountSliderVisible,
    cardLocked,
    closeAmountSlider,
    item,
    onLockedPress,
    onAction,
    pauseFreezeOptions,
    playSound,
    showEditorInline,
    allowThinkAction,
  ]);

  const handlePauseFreezeOptionPress = useCallback(
    (optionId) => {
      if (!optionId || optionId === pauseFreezeOptionId) return;
      setPauseFreezeOptionId(optionId);
      triggerSelectionHaptic();
      playSound?.("counter", { skipCooldown: true });
    },
    [pauseFreezeOptionId, playSound]
  );

  const handlePauseFreezeConfirm = useCallback(() => {
    const selectedOption = selectedPauseFreezeOption || pauseFreezeOptions[0];
    if (!selectedOption) {
      closePauseFreezePicker();
      return;
    }
    suppressCardPressUntilRef.current = Date.now() + 1200;
    triggerHaptic(Haptics.ImpactFeedbackStyle.Medium);
    const actionPayload = {
      freezeDurationMs: normalizeTemptationPauseFreezeDurationMs(selectedOption.durationMs),
      freezeOptionId: selectedOption.id,
    };
    closePauseFreezePicker({
      onClosed: () => {
        onAction?.("pause", item, actionPayload);
      },
    });
  }, [
    closePauseFreezePicker,
    item,
    onAction,
    pauseFreezeOptions,
    selectedPauseFreezeOption,
  ]);

  const handleAmountManualSave = useCallback(() => {
    const parsedLocal = parseNumberInputValue(amountManualValue);
    if (!Number.isFinite(parsedLocal) || parsedLocal <= 0) {
      setAmountManualError(t("coinEntryManualError"));
      return;
    }
    const normalizedLocal = snapCurrencyValue(parsedLocal, currency);
    const parsedUSD = clampTransactionAmountUSD(convertFromCurrency(normalizedLocal, currency));
    if (!Number.isFinite(parsedUSD) || parsedUSD <= 0) {
      setAmountManualError(t("coinEntryManualError"));
      return;
    }
    amountSliderBaseOverrideUSDRef.current = parsedUSD;
    amountSliderManualUSDRef.current = parsedUSD;
    setAmountSliderBaseOverrideUSD(parsedUSD);
    updateAmountSliderValue(0.5, { fromUser: false });
    markAmountSliderInteracted();
    setAmountManualVisible(false);
    setAmountManualError("");
    Keyboard.dismiss();
    triggerHaptic(Haptics.ImpactFeedbackStyle.Medium);
    playSound?.("tap", { skipCooldown: true });
  }, [amountManualValue, currency, markAmountSliderInteracted, playSound, t, updateAmountSliderValue]);

  const handleAmountSliderTouch = useCallback(
    (event) => {
      const width = amountSliderTrackWidthRef.current || amountSliderTrackWidth;
      if (!width) return;
      const pageX = Number(event?.nativeEvent?.pageX);
      if (!Number.isFinite(pageX)) return;
      const localX = pageX - amountSliderTrackPageXRef.current;
      const nextValue = localX / width;
      updateAmountSliderValue(nextValue, { fromUser: true });
    },
    [amountSliderTrackWidth, updateAmountSliderValue]
  );

  const amountSliderPanResponder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onMoveShouldSetPanResponder: () => true,
        onPanResponderGrant: (event) => {
          setAmountSliderDragging(true);
          notifyAmountSliderTouch(true);
          handleAmountSliderTouch(event);
        },
        onPanResponderMove: (event) => {
          handleAmountSliderTouch(event);
        },
        onPanResponderRelease: () => {
          updateAmountSliderValue(amountSliderValueRef.current, { force: true });
          setAmountSliderDragging(false);
          notifyAmountSliderTouch(false);
        },
        onPanResponderTerminate: () => {
          updateAmountSliderValue(amountSliderValueRef.current, { force: true });
          setAmountSliderDragging(false);
          notifyAmountSliderTouch(false);
        },
      }),
    [handleAmountSliderTouch, notifyAmountSliderTouch, updateAmountSliderValue]
  );

  const confirmAmountAction = useCallback(
    (actionType) => {
      const displayedAmountUSD = Number(amountSliderDisplayedAmountUSDRef.current);
      let normalizedAmountUSD =
        Number.isFinite(displayedAmountUSD) && displayedAmountUSD > 0 ? displayedAmountUSD : 0;
      if (!normalizedAmountUSD) {
        const manualAmountUSD = Number(amountSliderManualUSDRef.current);
        normalizedAmountUSD =
          Number.isFinite(manualAmountUSD) && manualAmountUSD > 0 ? manualAmountUSD : 0;
      }
      if (!normalizedAmountUSD) {
        normalizedAmountUSD = resolveAmountSliderAmount(
          amountSliderValueRef.current,
          amountSliderBaseOverrideUSDRef.current
        ).amountUSD;
      }
      normalizedAmountUSD = clampTransactionAmountUSD(normalizedAmountUSD);
      if (!Number.isFinite(normalizedAmountUSD) || normalizedAmountUSD <= 0) {
        triggerHaptic(Haptics.ImpactFeedbackStyle.Light);
        playSound?.("counter", { skipCooldown: true });
        return;
      }
      triggerHaptic(Haptics.ImpactFeedbackStyle.Medium);
      // Keep card-press suppressed longer so iOS doesn't reopen the edit sheet
      // on delayed responder/bubble events after save/spend confirmation.
      suppressCardPressUntilRef.current = Date.now() + 1200;
      closeAmountSlider();
      onAction?.(actionType, item, { amountUSD: normalizedAmountUSD });
      if (onAmountSliderConfirmCoachComplete) {
        requestAnimationFrame(() => {
          onAmountSliderConfirmCoachComplete();
        });
      }
    },
    [
      closeAmountSlider,
      item,
      onAction,
      onAmountSliderConfirmCoachComplete,
      playSound,
      resolveAmountSliderAmount,
    ]
  );

  const switchAmountSliderAction = useCallback(
    (actionType) => {
      if (actionType !== "save" && actionType !== "spend") return;
      if (amountSliderAction === actionType) return;
      setAmountSliderAction(actionType);
      triggerSelectionHaptic();
      playSound?.("tap", { skipCooldown: true });
    },
    [amountSliderAction, playSound]
  );

  const handleAmountModalActionPress = useCallback(
    (actionType) => {
      suppressCardPressUntilRef.current = Date.now() + 1200;
      if (amountSliderAction !== actionType) {
        switchAmountSliderAction(actionType);
        return;
      }
      confirmAmountAction(actionType);
    },
    [amountSliderAction, confirmAmountAction, switchAmountSliderAction]
  );

  const settleSwipeAtCenter = useCallback(() => {
    swipeSettlingRef.current = true;
    const finish = () => {
      swipeLastTranslateRef.current = 0;
      swipeThresholdReachedRef.current = false;
      swipeSettlingRef.current = false;
      swipeActionRef.current = false;
    };
    translateX.stopAnimation();
    if (reduceMotion) {
      translateX.setValue(0);
      finish();
      return;
    }
    Animated.timing(translateX, {
      toValue: 0,
      duration: 165,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    }).start(finish);
  }, [reduceMotion, translateX]);

  const completeSwipeAction = useCallback(
    (direction) => {
      swipeSettlingRef.current = true;
      const finish = () => {
        swipeLastTranslateRef.current = 0;
        swipeThresholdReachedRef.current = false;
        swipeSettlingRef.current = false;
        swipeActionRef.current = false;
        if (direction > 0) {
          onSwipeArchive(item);
        } else {
          onSwipeDelete(item);
        }
        requestAnimationFrame(() => {
          translateX.setValue(0);
        });
      };
      translateX.stopAnimation();
      if (reduceMotion) {
        finish();
        return;
      }
      const exitDistance = Math.max(swipeCardWidthRef.current + 32, SCREEN_WIDTH);
      Animated.timing(translateX, {
        toValue: direction * exitDistance,
        duration: 190,
        easing: Easing.out(Easing.cubic),
        useNativeDriver: true,
      }).start(({ finished }) => {
        if (finished) {
          finish();
          return;
        }
        swipeLastTranslateRef.current = 0;
        swipeThresholdReachedRef.current = false;
        swipeSettlingRef.current = false;
        swipeActionRef.current = false;
      });
    },
    [item, onSwipeArchive, onSwipeDelete, reduceMotion, translateX]
  );

  const handleSwipeRelease = useCallback(
    (gestureState = {}, { commit = true } = {}) => {
      suppressCardPressUntilRef.current = Date.now() + 300;
      const currentOffset = swipeLastTranslateRef.current;
      const vx = Number.isFinite(gestureState.vx) ? gestureState.vx : 0;
      const direction = currentOffset === 0 ? 0 : Math.sign(currentOffset);
      const distanceThreshold =
        direction > 0 ? archiveSwipeDistanceThreshold : deleteSwipeDistanceThreshold;
      const directionHasAction =
        direction > 0
          ? typeof onSwipeArchive === "function"
          : direction < 0
          ? typeof onSwipeDelete === "function"
          : false;
      const passedDistance = Math.abs(currentOffset) >= distanceThreshold;
      const passedFling =
        Math.abs(currentOffset) >= 26 && direction * vx >= 0.55;
      const shouldCommit =
        commit && canSwipeCard && directionHasAction && (passedDistance || passedFling);
      if (shouldCommit) {
        triggerHaptic(Haptics.ImpactFeedbackStyle.Medium);
        completeSwipeAction(direction);
        return;
      }
      settleSwipeAtCenter();
    },
    [
      archiveSwipeDistanceThreshold,
      canSwipeCard,
      completeSwipeAction,
      deleteSwipeDistanceThreshold,
      onSwipeArchive,
      onSwipeDelete,
      settleSwipeAtCenter,
    ]
  );

  const cardSwipeGesture = useMemo(
    () =>
      Gesture.Pan()
        .enabled(canSwipeCard && !amountSliderVisible)
        .activeOffsetX([-8, 8])
        .failOffsetY([-12, 12])
        .runOnJS(true)
        .onTouchesDown((event) => {
          const touch = event.changedTouches?.[0] || event.allTouches?.[0];
          swipeTouchStartRef.current = touch
            ? { x: touch.absoluteX, y: touch.absoluteY }
            : null;
          swipeHorizontalIntentRef.current = false;
        })
        .onTouchesMove((event) => {
          const start = swipeTouchStartRef.current;
          const touch = event.allTouches?.[0] || event.changedTouches?.[0];
          if (!start || !touch) return;
          const dx = touch.absoluteX - start.x;
          const dy = touch.absoluteY - start.y;
          if (Math.abs(dx) >= 4 && Math.abs(dx) > Math.abs(dy) * 1.1) {
            swipeHorizontalIntentRef.current = true;
            suppressCardPressUntilRef.current = Date.now() + 300;
          }
        })
        .onStart(() => {
          swipeGestureActiveRef.current = true;
          suppressCardPressUntilRef.current = Date.now() + 300;
          swipeActionRef.current = true;
          swipeThresholdReachedRef.current = false;
          swipeLastTranslateRef.current = 0;
          translateX.stopAnimation();
          translateX.setValue(0);
        })
        .onUpdate((event) => {
          if (!canSwipeCard) return;
          const gestureDx = Number.isFinite(event.translationX) ? event.translationX : 0;
          const offset = setSwipeTranslate(gestureDx);
          const threshold =
            offset > 0 ? archiveSwipeDistanceThreshold : deleteSwipeDistanceThreshold;
          const actionReady = Math.abs(offset) >= threshold;
          if (actionReady !== swipeThresholdReachedRef.current) {
            swipeThresholdReachedRef.current = actionReady;
            if (actionReady) {
              triggerSelectionHaptic();
            }
          }
        })
        .onEnd((event) => {
          swipeGestureActiveRef.current = false;
          handleSwipeRelease({
            vx: Number.isFinite(event.velocityX) ? event.velocityX / 1000 : 0,
          });
        })
        .onFinalize(() => {
          const wasSwipeActive = swipeGestureActiveRef.current;
          swipeGestureActiveRef.current = false;
          swipeHorizontalIntentRef.current = false;
          swipeTouchStartRef.current = null;
          if (!wasSwipeActive) return;
          handleSwipeRelease({}, { commit: false });
        }),
    [
      archiveSwipeDistanceThreshold,
      amountSliderVisible,
      canSwipeCard,
      deleteSwipeDistanceThreshold,
      handleSwipeRelease,
      setSwipeTranslate,
      translateX,
    ]
  );

  useEffect(() => {
  }, [messageActive]);

  useEffect(() => {
    if (!burstKey) return;
    const coins = Array.from({ length: 5 }).map((_, index) => ({
      id: `${burstKey}-${index}`,
      progress: new Animated.Value(0),
      offsetX: (Math.random() - 0.5) * 80,
      rotation: (Math.random() > 0.5 ? 1 : -1) * (200 + Math.random() * 160),
      delay: index * 80,
    }));
    setCoinBursts(coins);
    coins.forEach((coin) => {
      Animated.timing(coin.progress, {
        toValue: 1,
        duration: 900,
        delay: coin.delay,
        easing: Easing.out(Easing.quad),
        useNativeDriver: true,
      }).start();
    });
    const timeout = setTimeout(() => setCoinBursts([]), 1100);
    return () => clearTimeout(timeout);
  }, [burstKey]);

  const handleCardPress = useCallback(() => {
    if (Date.now() < suppressCardPressUntilRef.current) {
      return;
    }
    if (swipeActionRef.current) {
      swipeActionRef.current = false;
      return;
    }
    if (cardLocked) {
      onLockedPress?.(item);
      return;
    }
    if (amountSliderVisible) {
      closeAmountSlider();
      return;
    }
    if (!allowCardTapToEdit) return;
    onToggleEdit?.(item);
  }, [
    allowCardTapToEdit,
    amountSliderVisible,
    cardLocked,
    closeAmountSlider,
    item,
    onLockedPress,
    onToggleEdit,
  ]);
  const handleCardLongPress = useCallback(() => {
    if (
      typeof onLongPress !== "function" ||
      cardLocked ||
      isArchived ||
      showEditorInline ||
      isEditing ||
      amountSliderVisible ||
      pauseFreezeVisible ||
      swipeHorizontalIntentRef.current ||
      swipeGestureActiveRef.current ||
      Math.abs(swipeLastTranslateRef.current) >= 8
    ) {
      return;
    }
    suppressCardPressUntilRef.current = Date.now() + 1200;
    onLongPress();
  }, [
    amountSliderVisible,
    cardLocked,
    isArchived,
    isEditing,
    onLongPress,
    pauseFreezeVisible,
    showEditorInline,
  ]);
  const handleAmountCategoryBudgetPress = useCallback(() => {
    if (!hasCategoryBudget || typeof onCategoryBudgetPress !== "function") return;
    closeAmountSlider();
    requestAnimationFrame(() => {
      onCategoryBudgetPress({
        item,
        categoryId: categoryBudget?.id || null,
        categoryLabel: categoryBudgetLabel,
        hasLimit: hasCategoryBudgetLimit,
        limitUSD: categoryBudgetLimitUSD,
      });
    });
  }, [
    categoryBudget?.id,
    categoryBudgetLabel,
    categoryBudgetLimitUSD,
    closeAmountSlider,
    hasCategoryBudget,
    hasCategoryBudgetLimit,
    item,
    onCategoryBudgetPress,
  ]);
  const handleAmountTimerPress = useCallback(() => {
    closeAmountSlider();
    requestAnimationFrame(() => {
      onToggleEdit?.(item);
    });
  }, [closeAmountSlider, item, onToggleEdit]);
  const handleAmountGoalPress = useCallback(() => {
    closeAmountSlider();
    requestAnimationFrame(() => {
      if (typeof onEditGoalSelect === "function") {
        onEditGoalSelect(item);
      } else {
        onToggleEdit?.(item);
      }
    });
  }, [closeAmountSlider, item, onEditGoalSelect, onToggleEdit]);
  const timerAccentColor = timerDanger
