  const identitySurfaceBorder = colorWithAlpha(colors.primary, isDarkTheme ? 0.2 : 0.1);
  const metaBadgeBackground = colorWithAlpha(colors.text, isDarkTheme ? 0.08 : 0.045);
  const goalAccentColor = isDarkTheme ? "#C2A7FF" : "#6E4ED2";
