const resolveBugReportCopy = (language = DEFAULT_LANGUAGE) => {
  const normalizedLanguage = normalizeLanguage(language);
  const translationLanguage = resolveTranslationLanguage(normalizedLanguage);
  const source =
    BUG_REPORT_COPY[normalizedLanguage] ||
    BUG_REPORT_COPY[translationLanguage] ||
    BUG_REPORT_COPY.en;
  return localizeFallbackCopyStructure(source, normalizedLanguage);
};

const BugReportIcon = React.memo(function BugReportIcon({ color = "#111827", size = 18 }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
      <SvgPath
        d="M9 8.5h6c1.7 0 3 1.3 3 3v3.2c0 3-2.2 5.3-5.1 5.3h-1.8C8.2 20 6 17.7 6 14.7v-3.2c0-1.7 1.3-3 3-3Z"
        stroke={color}
        strokeWidth={1.8}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <SvgPath
        d="M8.5 4.5 10.2 7M15.5 4.5 13.8 7M6 12H3.8M20.2 12H18M6.2 16H4.4M19.6 16h-1.8M12 8.5V20"
        stroke={color}
        strokeWidth={1.8}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <SvgCircle cx={9.5} cy={12} r={0.85} fill={color} />
      <SvgCircle cx={14.5} cy={12} r={0.85} fill={color} />
    </Svg>
  );
});

const BugReportFab = React.memo(function BugReportFab({
  visible = false,
  topInset = 0,
  colors,
  language,
  onPress,
}) {
  const copy = resolveBugReportCopy(language);
  if (!visible) return null;
  const iconColor = colors?.text || "#111827";
  const backgroundRgb = parseColor(colors?.background || "#FFFFFF");
  const backgroundYiq = (backgroundRgb.r * 299 + backgroundRgb.g * 587 + backgroundRgb.b * 114) / 1000;
  const isDark = backgroundYiq < 145;
  const fallbackBackground = colorWithAlpha(colors?.card || "#FFFFFF", isDark ? 0.2 : 0.28);
  const overlayColor = colorWithAlpha(colors?.card || "#FFFFFF", isDark ? 0.1 : 0.16);
  return (
    <TouchableOpacity
      style={[
        styles.bugReportFab,
        {
          top: Math.max(0, (Number(topInset) || 0) - 4),
          backgroundColor: fallbackBackground,
          borderColor: colorWithAlpha(iconColor, 0.1),
          shadowColor: iconColor,
        },
      ]}
      activeOpacity={0.86}
      accessibilityRole="button"
      accessibilityLabel={copy.buttonLabel}
      onPress={onPress}
    >
      {isBlurViewAvailable() ? (
        <ExpoBlurView
          tint={isDark ? "dark" : "light"}
          intensity={Platform.OS === "android" ? 18 : 22}
          blurReductionFactor={
            Platform.OS === "android" ? ANDROID_EXPO_BLUR_REDUCTION_FACTOR : undefined
          }
          experimentalBlurMethod={Platform.OS === "android" ? "dimezisBlurView" : undefined}
          style={styles.bugReportFabBlur}
        />
      ) : null}
      <View style={[styles.bugReportFabTint, { backgroundColor: overlayColor }]} />
      <View style={styles.bugReportFabIcon}>
        <BugReportIcon color={iconColor} />
      </View>
    </TouchableOpacity>
  );
});

const BugReportModal = React.memo(function BugReportModal({
  visible = false,
  colors,
  language,
  keyboardInset = 0,
  topSafeInset = 0,
  onClose,
  onFilled,
  onSubmit,
}) {
  const copy = resolveBugReportCopy(language);
  const [description, setDescription] = useState("");
  const [steps, setSteps] = useState("");
  const [sending, setSending] = useState(false);
  const filledLoggedRef = useRef(false);
  const fieldsScrollRef = useRef(null);
  const fieldsScrollHeightRef = useRef(0);
  const fieldLayoutsRef = useRef({});
  const activeFieldRef = useRef(null);
  const descriptionReady = description.trim().length > 0;
  const submitDisabled = sending || !descriptionReady;
  const normalizedKeyboardInset = Math.max(0, Number(keyboardInset) || 0);
  const normalizedTopSafeInset = Math.max(0, Number(topSafeInset) || 0);
  const modalVerticalInset = Math.max(IS_SHORT_DEVICE ? 8 : 12, normalizedTopSafeInset);
  const modalSafeAreaStyle = useMemo(
    () => ({ paddingTop: modalVerticalInset, paddingBottom: modalVerticalInset }),
    [modalVerticalInset]
  );
  const registerFieldLayout = useCallback((fieldKey, event) => {
    const layoutY = event?.nativeEvent?.layout?.y;
    if (!Number.isFinite(layoutY)) return;
    fieldLayoutsRef.current[fieldKey] = layoutY;
  }, []);
  const scrollFocusedFieldIntoView = useCallback((fieldKey) => {
    if (!fieldKey) return;
    requestAnimationFrame(() => {
      const layoutY = fieldLayoutsRef.current[fieldKey];
      if (!Number.isFinite(layoutY)) return;
      const visibleHeight = Math.max(1, fieldsScrollHeightRef.current || 0);
      const targetY = Math.max(0, layoutY - visibleHeight * 0.36);
      fieldsScrollRef.current?.scrollTo?.({ y: targetY, animated: true });
    });
  }, []);
  const handleFieldFocus = useCallback(
    (fieldKey) => {
      activeFieldRef.current = fieldKey;
      scrollFocusedFieldIntoView(fieldKey);
    },
    [scrollFocusedFieldIntoView]
  );
  const handleFieldBlur = useCallback((fieldKey) => {
    if (activeFieldRef.current === fieldKey) activeFieldRef.current = null;
  }, []);
  useEffect(() => {
    if (!normalizedKeyboardInset || !activeFieldRef.current) return undefined;
    const timeout = setTimeout(
      () => scrollFocusedFieldIntoView(activeFieldRef.current),
      Platform.OS === "ios" ? 80 : 120
    );
    return () => clearTimeout(timeout);
  }, [normalizedKeyboardInset, scrollFocusedFieldIntoView]);
  useEffect(() => {
    if (visible) {
      filledLoggedRef.current = false;
    }
  }, [visible]);
  const markFilled = useCallback(
    (value) => {
      if (filledLoggedRef.current) return;
      if (!String(value || "").trim()) return;
      filledLoggedRef.current = true;
      onFilled?.();
    },
    [onFilled]
  );
  const handleDescriptionChange = useCallback(
    (value) => {
      setDescription(value);
      markFilled(value);
    },
    [markFilled]
  );
  const handleStepsChange = useCallback(
    (value) => {
      setSteps(value);
      markFilled(value);
    },
    [markFilled]
  );
  const handleSubmit = useCallback(async () => {
    if (!descriptionReady) {
      Alert.alert(copy.validationTitle, copy.validationMessage);
      return;
    }
    setSending(true);
    const didSubmit = await onSubmit?.({
      description: description.trim(),
      steps: steps.trim(),
    });
    setSending(false);
    if (didSubmit === false) return;
    setDescription("");
    setSteps("");
    onClose?.();
  }, [copy, description, descriptionReady, onClose, onSubmit, steps]);
  const handleClose = useCallback(() => {
    if (sending) return;
    onClose?.();
  }, [onClose, sending]);
  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      statusBarTranslucent
      onRequestClose={handleClose}
    >
      <View style={styles.bugReportModalRoot}>
        <TouchableWithoutFeedback onPress={handleClose}>
          <View style={styles.bugReportBackdrop} />
        </TouchableWithoutFeedback>
        <KeyboardAvoidingView
          style={styles.bugReportKeyboardAvoider}
          behavior={Platform.OS === "ios" ? "padding" : "height"}
          keyboardVerticalOffset={0}
          pointerEvents="box-none"
        >
          <View
            style={[styles.bugReportModalWrap, modalSafeAreaStyle]}
            pointerEvents="box-none"
          >
            <TouchableWithoutFeedback onPress={() => {}}>
              <View
                style={[
                  styles.bugReportModalCard,
                  { backgroundColor: colors.card, borderColor: colors.border },
                ]}
              >
              <View style={styles.bugReportHeaderRow}>
                <View style={styles.bugReportTitleBlock}>
                  <Text style={[styles.bugReportTitle, { color: colors.text }]}>
                    {copy.title}
                  </Text>
                  <Text style={[styles.bugReportSubtitle, { color: colors.muted }]}>
                    {copy.subtitle}
                  </Text>
                </View>
                <TouchableOpacity
                  onPress={handleClose}
                  style={styles.bugReportClose}
                  disabled={sending}
                  accessibilityRole="button"
                  accessibilityLabel={copy.cancel}
                >
                  <Text style={[styles.bugReportCloseText, { color: colors.muted }]}>×</Text>
                </TouchableOpacity>
              </View>
              <ScrollView
                ref={fieldsScrollRef}
                style={styles.bugReportFieldsScroll}
                contentContainerStyle={styles.bugReportFieldsScrollContent}
                keyboardShouldPersistTaps="handled"
                keyboardDismissMode={Platform.OS === "ios" ? "interactive" : "on-drag"}
                showsVerticalScrollIndicator={false}
                nestedScrollEnabled
                onLayout={(event) => {
                  fieldsScrollHeightRef.current = event?.nativeEvent?.layout?.height || 0;
                }}
              >
                <View
                  style={styles.bugReportField}
                  onLayout={(event) => registerFieldLayout("description", event)}
                >
                  <Text style={[styles.bugReportLabel, { color: colors.muted }]}>
                    {copy.descriptionLabel}
                  </Text>
                  <TextInput
                    value={description}
                    onChangeText={handleDescriptionChange}
                    placeholder={copy.descriptionPlaceholder}
                    placeholderTextColor={colorWithAlpha(colors.muted, 0.72)}
                    multiline
                    textAlignVertical="top"
                    onFocus={() => handleFieldFocus("description")}
                    onBlur={() => handleFieldBlur("description")}
                    style={[
                      styles.bugReportInput,
                      styles.bugReportDescriptionInput,
                      {
                        color: colors.text,
                        borderColor: colors.border,
                        backgroundColor: colors.background,
                      },
                    ]}
                  />
                </View>
                <View
                  style={styles.bugReportField}
                  onLayout={(event) => registerFieldLayout("steps", event)}
                >
                  <Text style={[styles.bugReportLabel, { color: colors.muted }]}>
                    {copy.stepsLabel}
                  </Text>
                  <TextInput
                    value={steps}
                    onChangeText={handleStepsChange}
                    placeholder={copy.stepsPlaceholder}
                    placeholderTextColor={colorWithAlpha(colors.muted, 0.72)}
                    multiline
                    textAlignVertical="top"
                    onFocus={() => handleFieldFocus("steps")}
                    onBlur={() => handleFieldBlur("steps")}
                    style={[
                      styles.bugReportInput,
                      styles.bugReportStepsInput,
                      {
                        color: colors.text,
                        borderColor: colors.border,
                        backgroundColor: colors.background,
                      },
                    ]}
                  />
                </View>
              </ScrollView>
              <View style={styles.bugReportActions}>
                <TouchableOpacity
                  style={[styles.bugReportSecondaryButton, { borderColor: colors.border }]}
                  activeOpacity={0.84}
                  onPress={handleClose}
                  disabled={sending}
                >
                  <Text style={[styles.bugReportSecondaryText, { color: colors.muted }]}>
                    {copy.cancel}
                  </Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[
                    styles.bugReportPrimaryButton,
                    {
                      backgroundColor: colors.text,
                      opacity: submitDisabled ? 0.46 : 1,
                    },
                  ]}
                  activeOpacity={submitDisabled ? 1 : 0.86}
                  onPress={handleSubmit}
                  disabled={submitDisabled}
                >
                  <Text style={[styles.bugReportPrimaryText, { color: colors.background }]}>
                    {sending ? copy.sending : copy.send}
                  </Text>
                </TouchableOpacity>
              </View>
              </View>
            </TouchableWithoutFeedback>
          </View>
        </KeyboardAvoidingView>
      </View>
    </Modal>
  );
});

