        monetization_exp_group_b: nextGroup === MONETIZATION_EXPERIMENT_GROUPS.B ? "1" : "0",
        monetization_exp_group_c: nextGroup === MONETIZATION_EXPERIMENT_GROUPS.C ? "1" : "0",
