        const stored = Object.fromEntries(pairs || []);
        const lastActiveAtRaw = stored?.[STORAGE_KEYS.TAMAGOTCHI_LAST_ACTIVE_AT] ?? null;
        const missYouNotificationIdRaw =
          stored?.[STORAGE_KEYS.TAMAGOTCHI_MISS_YOU_NOTIFICATION] ?? null;
