function App() {
  return (
    <GestureHandlerRootView style={styles.appGestureRoot}>
      <SafeAreaProvider initialMetrics={initialWindowMetrics || undefined}>
        <MotionPreferenceProvider>
          <AppContent />
        </MotionPreferenceProvider>
      </SafeAreaProvider>
    </GestureHandlerRootView>
  );
}

const SentryWrappedApp = Sentry.wrap(App);
SentryWrappedApp.displayName = "SentryWrappedApp";

export default SentryWrappedApp;

const StatusGlass = React.memo(
  function StatusGlass({
    height,
    safeHeight = height,
    offsetY = 0,
    backgroundColor = null,
    theme,
    blurAvailable = false,
    solid = false,
    layerStyle = null,
  }) {
    const gradientId = useMemo(() => `status-glass-${Math.random().toString(36).slice(2, 10)}`, []);
    const isDarkTheme = theme === "dark";
    const isAndroidStatusGlass = Platform.OS === "android";
    const safeHeightValue = Math.max(0, Math.min(height, Number(safeHeight) || 0));
    const fadeHeight = Math.max(0, height - safeHeightValue);
    const blurBandConfig = Platform.OS === "ios"
      ? [
          { progress: 0.22, intensity: 52, opacity: 0.42 },
          { progress: 0.38, intensity: 42, opacity: 0.34 },
          { progress: 0.54, intensity: 32, opacity: 0.27 },
          { progress: 0.7, intensity: 24, opacity: 0.2 },
          { progress: 0.84, intensity: 16, opacity: 0.13 },
          { progress: 0.94, intensity: 10, opacity: 0.07 },
        ]
      : isAndroidStatusGlass
      ? [
          // Android blur banding becomes visible under transparent dim layers when
          // multiple blur views overlap. Keep one continuous pass and let the SVG
          // fade handle the transition.
          { progress: 1, intensity: 20, opacity: 0.22 },
        ]
      : [
          { progress: 0.42, intensity: 14, opacity: 0.18 },
          { progress: 0.86, intensity: 8, opacity: 0.1 },
        ];
    const blurBands = blurBandConfig.map((band) => ({
      height: Math.min(height, safeHeightValue + Math.round(fadeHeight * band.progress)),
      intensity: band.intensity,
      opacity: band.opacity,
    }));
    const backgroundProbe =
      typeof backgroundColor === "string"
        ? backgroundColor
        : isDarkTheme
        ? "#0D1320"
        : "#FFFFFF";
    const overlayColor = backgroundProbe;
    const safeHeightRatioPercent = Math.round((safeHeightValue / Math.max(1, height)) * 100);
    const safeStopPercent = Math.max(0, Math.min(100, safeHeightRatioPercent));
    const fadeRangePercent = Math.max(1, 100 - safeStopPercent);
    const softTopStopPercent = safeStopPercent * 0.55;
    const upperStopPercent = safeStopPercent + fadeRangePercent * 0.16;
    const upperMidStopPercent = safeStopPercent + fadeRangePercent * 0.33;
    const midStopPercent = safeStopPercent + fadeRangePercent * 0.5;
    const lowerMidStopPercent = safeStopPercent + fadeRangePercent * 0.67;
    const lowStopPercent = safeStopPercent + fadeRangePercent * 0.82;
    const tailStopPercent = safeStopPercent + fadeRangePercent * 0.93;
    const nearClearStopPercent = safeStopPercent + fadeRangePercent * 0.985;
    const toPercent = (value) => `${Math.max(0, Math.min(100, value)).toFixed(2)}%`;
    const overlayTopOpacity = solid ? 1 : isAndroidStatusGlass ? 0.86 : 0.7;
    const overlaySoftTopOpacity = solid ? 1 : isAndroidStatusGlass ? 0.8 : 0.68;
    const overlaySafeOpacity = solid ? 1 : isAndroidStatusGlass ? 0.72 : 0.6;
    const overlayUpperOpacity = isAndroidStatusGlass ? (solid ? 0.58 : 0.48) : solid ? 0.53 : 0.5;
    const overlayUpperMidOpacity = isAndroidStatusGlass ? (solid ? 0.43 : 0.34) : solid ? 0.45 : 0.41;
    const overlayMidOpacity = isAndroidStatusGlass ? (solid ? 0.3 : 0.23) : solid ? 0.35 : 0.31;
    const overlayLowerMidOpacity = isAndroidStatusGlass ? (solid ? 0.2 : 0.15) : solid ? 0.26 : 0.23;
    const overlayLowOpacity = isAndroidStatusGlass ? (solid ? 0.12 : 0.09) : solid ? 0.18 : 0.15;
    const overlayTailOpacity = isAndroidStatusGlass ? (solid ? 0.065 : 0.045) : solid ? 0.1 : 0.08;
    const overlayNearClearOpacity = isAndroidStatusGlass ? (solid ? 0.025 : 0.018) : solid ? 0.045 : 0.035;
    const topOffset = -Math.max(0, Number(offsetY) || 0);

    const renderBlurBand = (bandHeight, bandOpacity, bandIntensity, key) => {
      const style = [
        styles.statusGlassBlurBand,
        {
          height: bandHeight,
          opacity: bandOpacity,
        },
      ];
      if (Platform.OS === "android" && shouldUseAndroidCommunityBlur()) {
        return (
          <AndroidBlurView
            key={key}
            blurType={isDarkTheme ? "dark" : "light"}
            blurAmount={bandIntensity}
            autoUpdate={ANDROID_BLUR_AUTO_UPDATE}
            reducedTransparencyFallbackColor="transparent"
            style={style}
          />
        );
      }
      return (
        <ExpoBlurView
          key={key}
          tint={isDarkTheme ? "dark" : "light"}
          intensity={bandIntensity}
          blurReductionFactor={
            Platform.OS === "android"
              ? Math.max(ANDROID_EXPO_BLUR_REDUCTION_FACTOR, 3)
              : undefined
          }
          experimentalBlurMethod={
            Platform.OS === "android" ? "dimezisBlurView" : undefined
          }
          style={style}
        />
      );
    };

    return (
      <View pointerEvents="none" style={[styles.statusGlass, { height, top: topOffset }, layerStyle]}>
        {blurAvailable
          ? blurBands.map((band, index) =>
              renderBlurBand(
                band.height,
                band.opacity,
                band.intensity,
                `status-blur-band-${index}`
              )
            )
          : null}
        <Svg style={StyleSheet.absoluteFill} pointerEvents="none">
          <Defs>
            <SvgLinearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <SvgStop offset="0%" stopColor={overlayColor} stopOpacity={overlayTopOpacity} />
              <SvgStop
                offset={toPercent(softTopStopPercent)}
                stopColor={overlayColor}
                stopOpacity={overlaySoftTopOpacity}
              />
              <SvgStop
                offset={toPercent(safeStopPercent)}
                stopColor={overlayColor}
                stopOpacity={overlaySafeOpacity}
              />
              <SvgStop
                offset={toPercent(upperStopPercent)}
                stopColor={overlayColor}
                stopOpacity={overlayUpperOpacity}
              />
              <SvgStop
                offset={toPercent(upperMidStopPercent)}
                stopColor={overlayColor}
                stopOpacity={overlayUpperMidOpacity}
              />
              <SvgStop
                offset={toPercent(midStopPercent)}
                stopColor={overlayColor}
                stopOpacity={overlayMidOpacity}
              />
              <SvgStop
                offset={toPercent(lowerMidStopPercent)}
                stopColor={overlayColor}
                stopOpacity={overlayLowerMidOpacity}
              />
              <SvgStop
                offset={toPercent(lowStopPercent)}
                stopColor={overlayColor}
                stopOpacity={overlayLowOpacity}
              />
              <SvgStop
                offset={toPercent(tailStopPercent)}
                stopColor={overlayColor}
                stopOpacity={overlayTailOpacity}
              />
              <SvgStop
                offset={toPercent(nearClearStopPercent)}
                stopColor={overlayColor}
                stopOpacity={overlayNearClearOpacity}
              />
              <SvgStop offset="100%" stopColor={overlayColor} stopOpacity={0} />
            </SvgLinearGradient>
          </Defs>
          <SvgRect x="0" y="0" width="100%" height="100%" fill={`url(#${gradientId})`} />
        </Svg>
      </View>
    );
  },
  (prevProps, nextProps) =>
    prevProps.height === nextProps.height &&
    prevProps.safeHeight === nextProps.safeHeight &&
    prevProps.offsetY === nextProps.offsetY &&
    prevProps.backgroundColor === nextProps.backgroundColor &&
    prevProps.theme === nextProps.theme &&
    prevProps.blurAvailable === nextProps.blurAvailable &&
    prevProps.solid === nextProps.solid &&
    prevProps.layerStyle === nextProps.layerStyle
);

