function NewPendingModal({
  visible,
  colors,
  t,
  currency,
  language = DEFAULT_LANGUAGE,
  data,
  onChange,
  onSubmit,
  onCancel,
  titleText = null,
  subtitleText = null,
  submitText = null,
  keyboardOffset = 0,
}) {
  const keyboardPaddingStyle = keyboardOffset ? { paddingBottom: keyboardOffset } : null;
  const resolvedTitle = typeof titleText === "string" && titleText.length ? titleText : t("newPendingTitle");
  const resolvedSubtitle =
    typeof subtitleText === "string" ? subtitleText : t("newPendingSubtitle");
  const resolvedSubmit = typeof submitText === "string" && submitText.length ? submitText : t("newPendingCreate");
  const isEditingPending =
    typeof data?.pendingId === "string" && data.pendingId.trim().length > 0;
  const freezeOptions = useMemo(
    () =>
      TEMPTATION_PAUSE_FREEZE_OPTIONS.map((option) => ({
        ...option,
        label: formatTemptationPauseFreezeLabel(option.durationMs, language),
      })),
    [language]
  );
  const selectedFreezeOptionId =
    typeof data?.freezeOptionId === "string" && data.freezeOptionId.trim().length
      ? data.freezeOptionId.trim()
      : DEFAULT_TEMPTATION_PAUSE_OPTION_ID;
  const selectedFreezeDurationMs = normalizeTemptationPauseFreezeDurationMs(
    data?.freezeDurationMs,
    freezeOptions.find((option) => option.id === selectedFreezeOptionId)?.durationMs ||
      DEFAULT_TEMPTATION_PAUSE_FREEZE_DURATION_MS
  );
  const modalAccent = colors.primary || colors.text;
  const modalOnAccent = colors.onPrimary || colors.background;
  const modalSurface = colors.surfaceElevated || colors.card;
  const inputSurface = colors.surfaceMuted || colorWithAlpha(colors.text, 0.05);
  const currentEmoji = data?.emoji || "❄️";
  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={onCancel}
      statusBarTranslucent
    >
      <TouchableWithoutFeedback onPress={() => dismissKeyboardOrRun(onCancel)}>
        <View style={[styles.quickModalBackdrop, keyboardPaddingStyle]}>
          <TouchableWithoutFeedback onPress={() => {}}>
            <View
              style={[
                styles.newPendingModalCard,
                { backgroundColor: modalSurface, borderColor: colors.border },
              ]}
            >
              <ScrollView
                style={styles.newPendingModalScroll}
                contentContainerStyle={styles.newPendingModalContent}
                keyboardShouldPersistTaps="handled"
                showsVerticalScrollIndicator={false}
                nestedScrollEnabled
              >
                <View style={styles.newPendingModalHeader}>
                  <View
                    style={[
                      styles.newPendingModalIcon,
                      {
                        backgroundColor: colorWithAlpha(modalAccent, 0.12),
                        borderColor: colorWithAlpha(modalAccent, 0.22),
                      },
                    ]}
                  >
                    <Text style={styles.newPendingModalIconText}>{currentEmoji}</Text>
                  </View>
                  <View style={styles.newPendingModalHeaderCopy}>
                    <Text style={[styles.newPendingModalTitle, { color: colors.text }]}>
                      {resolvedTitle}
                    </Text>
                    {resolvedSubtitle ? (
                      <Text style={[styles.newPendingModalSubtitle, { color: colors.muted }]}>
                        {resolvedSubtitle}
                      </Text>
                    ) : null}
                  </View>
                </View>
                <View style={styles.newPendingFieldStack}>
                  <View style={styles.newPendingField}>
                    <Text style={[styles.newPendingFieldLabel, { color: colors.muted }]}>
                      {t("newPendingNameLabel")}
                    </Text>
                    <TextInput
                      style={[
                        styles.newPendingInput,
                        { borderColor: colors.border, color: colors.text, backgroundColor: inputSurface },
                      ]}
                      placeholder={t("newPendingNameLabel")}
                      placeholderTextColor={colors.muted}
                      value={data.title}
                      onChangeText={(text) => onChange("title", text)}
                      returnKeyType="done"
                      blurOnSubmit
                      onSubmitEditing={Keyboard.dismiss}
                    />
                  </View>
                  <View style={styles.newPendingInlineFields}>
                    <View style={[styles.newPendingField, styles.newPendingAmountField]}>
                      <Text
                        style={[
                          styles.newPendingFieldLabel,
                          styles.newPendingInlineFieldLabel,
                          { color: colors.muted },
                        ]}
                      >
                        {t("newPendingAmountLabel", { currency: getCurrencyDisplayCode(currency) })}
                      </Text>
                      <TextInput
                        style={[
                          styles.newPendingInput,
                          { borderColor: colors.border, color: colors.text, backgroundColor: inputSurface },
                        ]}
                        placeholder={t("newPendingAmountLabel", { currency: getCurrencyDisplayCode(currency) })}
                        placeholderTextColor={colors.muted}
                        keyboardType="decimal-pad"
                        value={data.amount}
                        onChangeText={(text) => onChange("amount", text)}
                        returnKeyType="done"
                        blurOnSubmit
                        onSubmitEditing={Keyboard.dismiss}
                      />
                    </View>
                    <View style={[styles.newPendingField, styles.newPendingEmojiField]}>
                      <Text
                        style={[
                          styles.newPendingFieldLabel,
                          styles.newPendingInlineFieldLabel,
                          { color: colors.muted },
                        ]}
                        numberOfLines={2}
                      >
                        {t("newPendingEmojiLabel")}
                      </Text>
                      <TextInput
                        style={[
                          styles.newPendingInput,
                          styles.newPendingEmojiInput,
                          { borderColor: colors.border, color: colors.text, backgroundColor: inputSurface },
                        ]}
                        placeholder="✨"
                        placeholderTextColor={colors.muted}
                        value={data.emoji || ""}
                        onChangeText={(text) => onChange("emoji", limitEmojiInput(text))}
                        selectTextOnFocus
                        maxLength={EMOJI_INPUT_MAX_LENGTH}
                        returnKeyType="done"
                        blurOnSubmit
                        onSubmitEditing={Keyboard.dismiss}
                      />
                    </View>
                  </View>
                </View>
                {!isEditingPending && (
                  <View
                    style={[
                      styles.newPendingFreezeSection,
                      { backgroundColor: inputSurface, borderColor: colors.border },
                    ]}
                  >
                    <View style={styles.newPendingFreezeHeader}>
                      <Text style={[styles.newPendingFreezeTitle, { color: colors.text }]}>
                        {t("newPendingFreezeLabel")}
                      </Text>
                      <Text style={[styles.newPendingFreezeValue, { color: modalAccent }]}>
                        {formatTemptationPauseFreezeLabel(selectedFreezeDurationMs, language)}
                      </Text>
                    </View>
                    <View style={styles.newPendingFreezeOptions}>
                      {freezeOptions.map((option) => {
                        const selected = option.id === selectedFreezeOptionId;
                        return (
                          <TouchableOpacity
                            key={option.id}
                            style={[
                              styles.newPendingFreezeChip,
                              {
                                borderColor: selected
                                  ? colorWithAlpha(modalAccent, 0.55)
                                  : colorWithAlpha(colors.border, 0.9),
                                backgroundColor: selected
                                  ? colorWithAlpha(modalAccent, 0.14)
                                  : modalSurface,
                              },
                            ]}
                            activeOpacity={0.88}
                            accessibilityRole="button"
                            accessibilityState={{ selected }}
                            onPress={() => {
                              onChange("freezeOptionId", option.id);
                              onChange("freezeDurationMs", option.durationMs);
                            }}
                          >
                            <Text style={styles.newPendingFreezeChipIcon}>{option.icon}</Text>
                            <Text
                              style={[
                                styles.newPendingFreezeChipText,
                                { color: selected ? colors.text : colors.muted },
                              ]}
                              numberOfLines={2}
                            >
                              {option.label}
                            </Text>
                          </TouchableOpacity>
                        );
                      })}
                    </View>
                    <Text style={[styles.newPendingFreezeHint, { color: colors.muted }]}>
                      {t("newPendingFreezeHint", {
                        duration: formatTemptationPauseFreezeLabel(selectedFreezeDurationMs, language),
                      })}
                    </Text>
                  </View>
                )}
                <View style={styles.newPendingModalActions}>
                  <TouchableOpacity
                    style={[
                      styles.newPendingModalSecondary,
                      { borderColor: colors.border, backgroundColor: inputSurface },
                    ]}
                    onPress={onCancel}
                    activeOpacity={0.82}
                  >
                    <Text
                      style={[styles.newPendingModalSecondaryText, { color: colors.text }]}
                      numberOfLines={1}
                      adjustsFontSizeToFit
                      minimumFontScale={0.82}
                    >
                      {t("newPendingCancel")}
                    </Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={[styles.newPendingModalPrimary, { backgroundColor: modalAccent }]}
                    onPress={onSubmit}
                    activeOpacity={0.86}
                  >
                    <Text
                      style={[styles.newPendingModalPrimaryText, { color: modalOnAccent }]}
                      numberOfLines={1}
                      adjustsFontSizeToFit
                      minimumFontScale={0.82}
                    >
                      {resolvedSubmit}
                    </Text>
                  </TouchableOpacity>
                </View>
              </ScrollView>
            </View>
          </TouchableWithoutFeedback>
        </View>
      </TouchableWithoutFeedback>
    </Modal>
  );
}

