const FallingCoin = ({ left, size, delay, duration }) => {
  const progress = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    const animation = Animated.sequence([
      Animated.delay(delay),
      Animated.timing(progress, {
        toValue: 1,
        duration,
        easing: Easing.in(Easing.quad),
        useNativeDriver: true,
      }),
    ]);
    animation.start();
    return () => animation.stop();
  }, [delay, duration, progress]);

  const translateY = progress.interpolate({
    inputRange: [0, 1],
    outputRange: [-80, Dimensions.get("window").height],
  });
  const rotate = progress.interpolate({
    inputRange: [0, 1],
    outputRange: ["-40deg", "40deg"],
  });
  const opacity = progress.interpolate({
    inputRange: [0, 0.1, 0.9, 1],
    outputRange: [0, 1, 1, 0],
  });

  return (
    <Animated.View
      pointerEvents="none"
      style={[
        styles.levelCoin,
        {
          width: size,
          height: size,
          left,
          opacity,
          transform: [{ translateY }, { rotate }],
        },
      ]}
    />
  );
};

const getRandomFinancialQuote = (language) => {
  const normalized = normalizeLanguage(language);
  const translationLanguage = resolveTranslationLanguage(normalized);
  const pool = FINANCIAL_QUOTES.map((entry) => {
    const raw = entry[normalized] || entry[translationLanguage] || entry.en;
    return localizeFallbackTextByLanguage(raw, normalized);
  }).filter(Boolean);
  if (!pool.length) return "";
  return pool[Math.floor(Math.random() * pool.length)];
};

